// import { hey } from "./hey";

/**
 * Check if user prefers reduced motion
 * @returns {boolean} True if user prefers reduced motion
 */
export const prefersReducedMotion = (): boolean => {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
};

/**
 * Check if viewport width is tablet or smaller (<=1024px)
 * @returns {boolean} True if viewport is tablet or smaller
 */
export const isTabletOrBelow = (): boolean => {
  return window.matchMedia("(max-width: 1024px)").matches;
};

/**
 * Check if viewport width is mobile (<=768px)
 * @returns {boolean} True if viewport is mobile
 */
export const isMobile = (): boolean => {
  let check = false;
  (function (a) {
    if (
      /(android|bb\d+|meego).+mobile|avantgo|bada\/|blackberry|blazer|compal|elaine|fennec|hiptop|iemobile|ip(hone|od)|iris|kindle|lge |maemo|midp|mmp|mobile.+firefox|netfront|opera m(ob|in)i|palm( os)?|phone|p(ixi|re)\/|plucker|pocket|psp|series(4|6)0|symbian|treo|up\.(browser|link)|vodafone|wap|windows ce|xda|xiino|android|ipad|playbook|silk/i.test(
        a
      ) ||
      /1207|6310|6590|3gso|4thp|50[1-6]i|770s|802s|a wa|abac|ac(er|oo|s\-)|ai(ko|rn)|al(av|ca|co)|amoi|an(ex|ny|yw)|aptu|ar(ch|go)|as(te|us)|attw|au(di|\-m|r |s )|avan|be(ck|ll|nq)|bi(lb|rd)|bl(ac|az)|br(e|v)w|bumb|bw\-(n|u)|c55\/|capi|ccwa|cdm\-|cell|chtm|cldc|cmd\-|co(mp|nd)|craw|da(it|ll|ng)|dbte|dc\-s|devi|dica|dmob|do(c|p)o|ds(12|\-d)|el(49|ai)|em(l2|ul)|er(ic|k0)|esl8|ez([4-7]0|os|wa|ze)|fetc|fly(\-|_)|g1 u|g560|gene|gf\-5|g\-mo|go(\.w|od)|gr(ad|un)|haie|hcit|hd\-(m|p|t)|hei\-|hi(pt|ta)|hp( i|ip)|hs\-c|ht(c(\-| |_|a|g|p|s|t)|tp)|hu(aw|tc)|i\-(20|go|ma)|i230|iac( |\-|\/)|ibro|idea|ig01|ikom|im1k|inno|ipaq|iris|ja(t|v)a|jbro|jemu|jigs|kddi|keji|kgt( |\/)|klon|kpt |kwc\-|kyo(c|k)|le(no|xi)|lg( g|\/(k|l|u)|50|54|\-[a-w])|libw|lynx|m1\-w|m3ga|m50\/|ma(te|ui|xo)|mc(01|21|ca)|m\-cr|me(rc|ri)|mi(o8|oa|ts)|mmef|mo(01|02|bi|de|do|t(\-| |o|v)|zz)|mt(50|p1|v )|mwbp|mywa|n10[0-2]|n20[2-3]|n30(0|2)|n50(0|2|5)|n7(0(0|1)|10)|ne((c|m)\-|on|tf|wf|wg|wt)|nok(6|i)|nzph|o2im|op(ti|wv)|oran|owg1|p800|pan(a|d|t)|pdxg|pg(13|\-([1-8]|c))|phil|pire|pl(ay|uc)|pn\-2|po(ck|rt|se)|prox|psio|pt\-g|qa\-a|qc(07|12|21|32|60|\-[2-7]|i\-)|qtek|r380|r600|raks|rim9|ro(ve|zo)|s55\/|sa(ge|ma|mm|ms|ny|va)|sc(01|h\-|oo|p\-)|sdk\/|se(c(\-|0|1)|47|mc|nd|ri)|sgh\-|shar|sie(\-|m)|sk\-0|sl(45|id)|sm(al|ar|b3|it|t5)|so(ft|ny)|sp(01|h\-|v\-|v )|sy(01|mb)|t2(18|50)|t6(00|10|18)|ta(gt|lk)|tcl\-|tdg\-|tel(i|m)|tim\-|t\-mo|to(pl|sh)|ts(70|m\-|m3|m5)|tx\-9|up(\.b|g1|si)|utst|v400|v750|veri|vi(rg|te)|vk(40|5[0-3]|\-v)|vm40|voda|vulc|vx(52|53|60|61|70|80|81|83|85|98)|w3c(\-| )|webc|whit|wi(g |nc|nw)|wmlb|wonu|x700|yas\-|your|zeto|zte\-/i.test(
        a.substr(0, 4)
      )
    )
      check = true;
  })(navigator.userAgent || navigator.vendor || window.opera);
  return check;
};

import gsap from 'gsap'

import { DrawSVGPlugin } from 'gsap/DrawSVGPlugin'
import { CustomEase } from 'gsap/CustomEase'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { MorphSVGPlugin } from 'gsap/MorphSVGPlugin'
import { TextPlugin } from 'gsap/TextPlugin'
import { Flip } from 'gsap/Flip'
import { SplitText } from 'gsap/SplitText'

import { prefersReducedMotion } from './utils/media'

gsap.registerPlugin(SplitText, DrawSVGPlugin, CustomEase, ScrollTrigger, MorphSVGPlugin, TextPlugin, Flip)

ScrollTrigger.refresh()

const easeMenu = CustomEase.create('custom', 'M0,0 C0.61,-0.01 0,1 1,1')
const easePrimary = CustomEase.create('customEase', '0.6, 0.01, 0.05, 1')
const easeDirectional = CustomEase.create('directionalEase', '0.16, 1, 0.3, 1')
const easeBlur = CustomEase.create('smoothBlur', '0.25, 0.1, 0.25, 1')
const easeGentleIn = CustomEase.create('gentleIn', '0.38, 0.005, 0.215, 1.1')
const easeQuickSnap = CustomEase.create('quickSnap', '0.22, 1, 0.36, 1')
const easeInstant = CustomEase.create('instantEase', '0.1, 0, 0, 1')
const easeText = CustomEase.create('cssEase', '0.215, 0.61, 0.355, 1')

const defaults = {
  ease: 'expo.out',
  duration: 1.2,
}

gsap.defaults(defaults)

const reduced = prefersReducedMotion()

export default gsap
export { defaults, ScrollTrigger, SplitText, Flip, reduced, easeMenu, easePrimary, easeDirectional, easeBlur, easeGentleIn, easeQuickSnap, easeInstant, easeText }

import Lenis from 'lenis'
import gsap from '@/gsap'

interface ScrollEvent {
  scroll: number
  limit: number
  velocity: number
  progress: number
}

type ScrollCallback = (event: ScrollEvent) => void
type Unsubscribe = () => void

const SCROLL_CONFIG = {
  autoResize: true,
  // infinite: true,
  syncTouch: true,
  syncTouchLerp: 0.1,
  // wrapper: document.body,
  // content: document.body,
  // lerp: 0.025,
  wheelMultiplier: 0.25,
  duration: 3,
  // easing: (x: number): number => Math.min(1, 1.001 - Math.pow(2, -10 * x)),
  // smoothWheel: true,
  // smoothTouch: false,
  // touchMultiplier: 2,
  // touchInertiaMultiplier: 2,
}

class _Scroll extends Lenis {
  #subscribers: {
    fn: ScrollCallback
    id: Symbol
    priority: number
  }[] = []

  #resizeObserver: ResizeObserver | null = null

  y: number
  max: number
  speed: number
  percent: number

  constructor() {
    super(SCROLL_CONFIG)
    this.y = window.scrollY || 0
    this.max = window.innerHeight
    this.speed = 0
    this.percent = 0
    this.#init()
  }

  #init(): void {
    this.percent = this.y / (document.body.scrollHeight - this.max)

    this.on('scroll', this.#handleScroll)
    gsap.ticker.add((time: number) => this.raf(time * 1000))

    this.observeHeight(() => {
      if (typeof this.resize === 'function') {
        this.resize()
      }
    })
  }

  #handleScroll = ({ scroll, limit, velocity, progress }: ScrollEvent): void => {
    this.y = scroll
    this.max = limit
    this.speed = velocity
    this.percent = progress
    // console.log("scroll", scroll, limit, velocity, progress);

    this.#subscribers.forEach((subscriber) => {
      subscriber.fn({ scroll, limit, velocity, progress })
      // console.log("subscriber scroll", subscriber, scroll, limit, velocity, progress);
    })
  }

  subscribe(fn: ScrollCallback, priority = 5, id = Symbol()): Unsubscribe {
    const subscriber = { fn, id, priority }
    const index = this.#subscribers.findIndex((sub) => sub.priority <= priority)

    if (index === -1) {
      this.#subscribers.push(subscriber)
    } else {
      this.#subscribers.splice(index, 0, subscriber)
    }

    return () => this.#unsubscribe(id)
  }

  #unsubscribe(id: Symbol): void {
    this.#subscribers = this.#subscribers.filter((subscriber) => subscriber.id !== id)
  }

  toTop(): void {
    this.scrollTo(0, { immediate: true, force: true })
  }

  observeHeight(callback: (height: number) => void): Unsubscribe {
    if (this.#resizeObserver) {
      this.#resizeObserver.disconnect()
    }

    this.#resizeObserver = new ResizeObserver((entries: ResizeObserverEntry[]) => {
      for (const entry of entries) {
        callback(entry.target.scrollHeight)
      }
    })

    this.#resizeObserver.observe(document.body)
    return () => this.#resizeObserver?.disconnect()
  }
}

export const Scroll = new _Scroll()

import gsap from "@/gsap";
import { App } from "@/app";
import { isMobile } from "./media";

export class Subscribable {
  // #subscribers = [];
  #subscribers: { fn: (time: number) => void, id: Symbol, priority: number }[] = [];
  isMobile = isMobile();

  subscribe(fn: (time: number) => void, priority = 5, id = Symbol()) {
    const subscriber = { fn, id, priority };

    const index = this.#subscribers.findIndex(
      (sub) => sub.priority <= priority
    );

    if (index === -1) {
      this.#subscribers.push(subscriber);
    } else {
      this.#subscribers.splice(index, 0, subscriber);
    }

    return () => this.#unsubscribe(id);
  }

  #unsubscribe(id: Symbol) {
    this.#subscribers = this.#subscribers.filter(
      (subscriber) => subscriber.id !== id
    );
  }

  set subs(value: any) {
    this.#subscribers.forEach((subscriber) => subscriber.fn(value));
  }
}

class _Resize extends Subscribable {
  #observer: ResizeObserver;
  window = {
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
  };

  constructor() {
    super();
    this.#observer = new ResizeObserver(this.handleResize);
    this.#observer.observe(document.body);
  }

  handleResize = (entries: ResizeObserverEntry[]) => {
    const entry = entries[0];
    if (!entry) return;

    this.isMobile = isMobile();

    this.window.innerWidth = window.innerWidth;
    this.window.innerHeight = window.innerHeight;

    this.subs = {
      width: this.window.innerWidth,
      height: this.window.innerHeight,
    };

    document.documentElement.style.setProperty(
      "--vw",
      `${this.window.innerWidth * 0.01}px`
    );
    document.documentElement.style.setProperty(
      "--vh",
      `${this.window.innerHeight * 0.01}px`
    );
  };

  observe(element: Element) {
    this.#observer.observe(element);
  }

  unobserve(element: Element) {
    this.#observer.unobserve(element);
  }
}

export class _Raf extends Subscribable {
  time = 0;
  deltaTime = 0;
  frame = 0;

  constructor() {
    super();
    gsap.ticker.add(this.raf);
  }

  raf = (time: number, deltaTime: number, frame: number) => {
    this.time = time;
    this.deltaTime = deltaTime / 1000;
    this.frame = frame;

    this.subs = {
      time,
      deltaTime,
      frame,
    };
  };
}

export const Resize = new _Resize();
export const Raf = new _Raf();

import { Scroll } from "../scroll";
import { Resize } from "./subscribable";
// import { Gl } from "../gl/gl"

export const clientRect = (element) => {
  const bounds = element.getBoundingClientRect();

  return {
    top: bounds.top + Scroll.y,
    bottom: bounds.bottom + Scroll.y,
    width: bounds.width,
    height: bounds.height,
    left: bounds.left,
    right: bounds.right,
    wh: Resize.window.innerHeight,
    ww: Resize.window.innerWidth,
    offset: bounds.top + Scroll.y,
    centery:
      Resize.window.innerHeight / 2 - bounds.height / 2 - bounds.top - Scroll.y,
    centerx: -Resize.window.innerWidth / 2 + bounds.left + bounds.width / 2,
  };
};

export const clientRectGl = (element, ratio = 1) => {
  const bounds = clientRect(element);
  for (const [key, value] of Object.entries(bounds))
    bounds[key] = value * ratio;
  return bounds;
};

import { Raf } from "./subscribable"

/** ------------ Damp/Lerp **/

/**
 * Framerate independent dampening using power-based smoothing
 * @param current - The current value
 * @param target - The target value to transition towards
 * @param smoothing - Smoothing factor (larger = smoother/slower, recommended: 0.001 to 1)
 * @param dt - Delta time in seconds
 * @returns Interpolated value between current and target
 */
export function dampPow(
  current: number,
  target: number,
  smoothing: number,
  dt: number = Raf.deltaTime
): number {
  return lerp(current, target, 1 - Math.pow(smoothing, dt))
}

/**
 * Framerate independent dampening using exponential decay
 * @param current - The current value
 * @param target - The target value to transition towards
 * @param lambda - Decay rate (larger = faster decay)
 * @param dt - Delta time in seconds
 * @returns Interpolated value between current and target
 */
export function damp(
  current: number,
  target: number,
  lambda: number,
  dt: number = Raf.deltaTime
): number {
  // console.log(Raf.deltaTime, current, target, lambda)
  return lerp(current, target, 1 - Math.exp(-lambda * dt))
}

export function lerp(v0: number, v1: number, t: number): number {
  return v0 * (1 - t) + v1 * t
}

/** ------------ Map/Clamp **/
export function map(
  value: number,
  low1: number,
  high1: number,
  low2: number,
  high2: number
): number {
  return low2 + ((high2 - low2) * (value - low1)) / (high1 - low1)
}

export function clamp(min: number, max: number, num: number): number {
  return Math.min(Math.max(num, min), max)
}

/** ------------ Angles **/
export function radToDeg(r: number): number {
  return (r * 180) / Math.PI
}

export function degToRad(d: number): number {
  return (d * Math.PI) / 180
}

/** ------------ Bitwise **/
export const isPowerOfTwo = (n: number): boolean => !!n && (n & (n - 1)) === 0

export function symmetricMod(value: number, base: number): number {
  let m = value % base
  if (Math.abs(m) > base / 2) {
    m = m > 0 ? m - base : m + base
  }
  return m
}

export const roundNumber = (number: number, precision = 2) => {
  return Number.parseFloat(number.toPrecision(precision));
};

interface ObserveConfig {
  root?: HTMLElement | null;
  rootMargin?: string;
  threshold?: number;
  autoStart?: boolean;
  once?: boolean;
  callback?: (data: ObserveEventData) => void;
}

interface ObserveEventData {
  entry: IntersectionObserverEntry;
  direction: number;
}

interface ObserverGroup {
  config: ObserveConfig;
  observer: IntersectionObserver;
  elements: Map<
    HTMLElement,
    {
      callbacks: {
        isIn?: (data: ObserveEventData) => void;
        isOut?: (data: ObserveEventData) => void;
        callback?: (data: any) => void;
      };
      once: boolean;
      lastDirection?: number;
    }
  >;
}

export class ObserverManager {
  private static instance: ObserverManager;
  private groups: ObserverGroup[] = [];

  private constructor() { }

  static getInstance(): ObserverManager {
    if (!ObserverManager.instance) {
      ObserverManager.instance = new ObserverManager();
    }
    return ObserverManager.instance;
  }

  private configsMatch(
    config1: ObserveConfig,
    config2: ObserveConfig
  ): boolean {
    return (
      config1.root === config2.root &&
      config1.rootMargin === config2.rootMargin &&
      config1.threshold === config2.threshold
    );
  }

  private handleIntersection(entries: IntersectionObserverEntry[]) {
    entries.forEach((entry) => {
      const group = this.groups.find((g) => {
        return Array.from(g.elements.keys()).includes(
          entry.target as HTMLElement
        );
      });

      if (!group) return;

      const element = entry.target as HTMLElement;
      const elementData = group.elements.get(element);
      if (!elementData) return;

      const { isIntersecting, intersectionRatio, boundingClientRect } = entry;
      const threshold = group.config.threshold || 0.1;

      let direction = -1;
      if (elementData.lastDirection !== undefined) {
        direction = isIntersecting
          ? boundingClientRect.top > 0
            ? 1
            : -1
          : boundingClientRect.top > 0
            ? -1
            : 1;
      }
      elementData.lastDirection = direction;

      if (intersectionRatio === 0) {
        elementData.callbacks.isOut?.({ entry, direction });
        elementData.callbacks.callback?.({ entry, direction, isIn: false });
      } else if (intersectionRatio >= threshold) {
        elementData.callbacks.isIn?.({ entry, direction });
        elementData.callbacks.callback?.({ entry, direction, isIn: true });

        if (elementData.once) {
          this.removeElement(element);
        }
      }
    });
  }

  addElement(
    element: HTMLElement,
    config: ObserveConfig,
    callbacks: {
      isIn?: (data: ObserveEventData) => void;
      isOut?: (data: ObserveEventData) => void;
      callback?: (data: any) => void;
    }
  ): ObserverGroup {
    this.removeElement(element);

    let group = this.groups.find((g) => this.configsMatch(g.config, config));

    if (!group) {
      const observer = new IntersectionObserver(
        (entries) => this.handleIntersection(entries),
        {
          ...config,
          threshold: [0, config.threshold || 0.1],
        }
      );

      group = {
        config,
        observer,
        elements: new Map(),
      };
      this.groups.push(group);
    }

    group.elements.set(element, {
      callbacks,
      once: config.once || false,
      lastDirection: undefined,
    });
    group.observer.observe(element);

    return group;
  }

  removeElement(element: HTMLElement) {
    const group = this.groups.find((g) => g.elements.has(element));
    if (!group) return;

    group.observer.unobserve(element);
    group.elements.delete(element);

    if (group.elements.size === 0) {
      group.observer.disconnect();
      this.groups = this.groups.filter((g) => g !== group);
    }
  }
}

export class Observe {
  element: HTMLElement;
  #config: ObserveConfig;
  #group: ObserverGroup;
  protected isIn(data: ObserveEventData): void { }
  protected isOut(data: ObserveEventData): void { }

  inView: boolean;
  callback: ({
    entry,
    direction,
    isIn,
  }: {
    entry: IntersectionObserverEntry;
    direction: number;
    isIn: boolean;
  }) => void;

  #lastDirection: number | null = null;
  #wasIntersecting: boolean | null = null;

  constructor(
    element: HTMLElement,
    config: ObserveConfig = {
      root: null,
      rootMargin: "0px",
      threshold: 0.1,
      autoStart: false,
      once: false,
      callback: null,
    }
  ) {
    this.element = element;
    this.#config = config;
    this.inView = false;
    this.callback = config.callback;
  }

  start() {
    this.#group = ObserverManager.getInstance().addElement(
      this.element,
      this.#config,
      {
        isIn: (data) => {
          this.inView = true;
          this.isIn?.(data);
        },
        isOut: (data) => {
          this.inView = false;
          this.isOut?.(data);
        },
        callback: this.callback,
      }
    );
  }

  stop() {
    ObserverManager.getInstance().removeElement(this.element);
  }

  destroy() {
    this.stop();
    this.#lastDirection = null;
    this.#wasIntersecting = null;
  }

  transitionOut() {
    this.destroy();
  }
}

import { clientRect } from "@/utils/client-rect";
import { clamp, map } from "@/utils/math";
import { Observe } from "./observe";
import { Scroll } from "@/scroll";
import { Resize } from "@/utils/subscribable";

type Position = "top" | "center" | "bottom" | number; // Now supports values >100 and <0

const DEFAULT_CONFIG: {
  bounds: [number, number];
  top: Position;
  bottom: Position;
  callback?: (value: number) => void;
  cssVariable?: string;
} = {
  bounds: [0, 1],
  top: "bottom", // 0%
  bottom: "top", // 100%
  callback: undefined,
  cssVariable: "--progress",
};

export class Track extends Observe {
  value = 0;
  #init = false;

  bounds: any;
  config: {
    bounds: [number, number];
    top: Position;
    bottom: Position;
    callback?: (value: number) => void;
    cssVariable?: string;
  };

  protected resize?: (bounds: any) => void;
  protected handleScroll?: (value: number) => void;

  #scrollSub: () => void;
  #resizeSub: () => void;

  constructor(
    element: HTMLElement,
    config: Partial<typeof DEFAULT_CONFIG> = {}
  ) {
    super(element, {
      autoStart: false,
      once: false,
      threshold: 0,
    });

    this.element = element;

    // Parse data-scroll-offset attribute if it exists
    const dataOffsets = this.#parseDataScrollOffset();

    this.config = {
      ...DEFAULT_CONFIG,
      top: dataOffsets?.top ?? config.top ?? DEFAULT_CONFIG.top,
      bottom: dataOffsets?.bottom ?? config.bottom ?? DEFAULT_CONFIG.bottom,
      bounds: config.bounds ?? DEFAULT_CONFIG.bounds,
      callback: config.callback,
      cssVariable: config.cssVariable,
    };

    this.#updateCssVariable(0);
    this.#resize();
    this.#scrollSub = Scroll.subscribe(this.#handleScroll);
    this.#resizeSub = Resize.subscribe(this.#resize);
    this.#handleScroll();
    this.#init = true;
  }

  // Parse data-scroll-offset attribute
  #parseDataScrollOffset(): { top: number; bottom: number } | null {
    const offsetString = this.element.getAttribute('data-scroll-offset');
    if (!offsetString) return null;

    const offsets = offsetString.split(',').map(s => s.trim());
    if (offsets.length !== 2) return null;

    const top = parseFloat(offsets[0]);
    const bottom = parseFloat(offsets[1]);

    if (isNaN(top) || isNaN(bottom)) return null;

    return { top, bottom };
  }

  triggerResize() {
    this.#resize();
  }

  #resize = () => {
    this.bounds = computeBounds(this.element, this.config);
    this.resize?.(this.bounds);
    this.#handleScroll();
  };

  #handleScroll = () => {
    if (!this.inView || !this.#init) return;

    this.value = clamp(
      this.config.bounds[0],
      this.config.bounds[1],
      map(
        Scroll.y,
        this.bounds.top,
        this.bounds.bottom,
        this.config.bounds[0],
        this.config.bounds[1]
      )
    );

    this.#updateCssVariable(this.value);
    this.handleScroll?.(this.value);
    this.config.callback?.(this.value);
  };

  #updateCssVariable(value: number) {
    const varName = this.config.cssVariable || "--progress";
    this.element.style.setProperty(varName, String(value));
  }

  destroy() {
    this.config.callback = undefined;
    this.#scrollSub();
    this.#resizeSub();
    const varName = this.config.cssVariable || "--progress";
    this.element.style.removeProperty(varName);
    super.destroy();
  }

  transitionOut() {
    this.destroy();
  }
}

function positionToPercentage(position: Position): number {
  if (typeof position === 'number') {
    // No longer clamping to 0-100, allowing any number
    return position / 100;
  }
  switch (position) {
    case 'top': return 1;    // 100%
    case 'center': return 0.5; // 50%
    case 'bottom': return 0;  // 0%
    default: return 0;
  }
}

function computeBounds(el: HTMLElement, config: typeof DEFAULT_CONFIG) {
  const bounds = clientRect(el);
  const { top: topPos, bottom: bottomPos, wh } = bounds;

  const topPercentage = positionToPercentage(config.top);
  const bottomPercentage = positionToPercentage(config.bottom);

  // Calculate offsets - now supports values beyond viewport height
  bounds.top = topPos - (wh * (1 - topPercentage));
  bounds.bottom = bottomPos - (wh * (1 - bottomPercentage));

  return bounds;
}

const html = document.documentElement
const body = document.body
