let currentOpenAccordion = null;

export class Accordion extends Observe {
  constructor(element) {
    super(element);

    // DOM 
    this.$details = element;

    // Binding
    this.onClickBind = this.onClick.bind(this);

    // Data
    this.animation = null;
    this.isClosing = false;
    this.isExpanding = false;
  }

  init() {
    // UI
    this.$summary = this.$details.querySelector("summary");
    this.$content = this.$details.querySelector(".accordion__content");
    this.bindEvents();

    // Close if another accordion is open
    if (currentOpenAccordion && currentOpenAccordion !== this && this.$details.open) {
      this.shrink();
    }
  }

  destroy() {
    super.destroy();

    // this.unbindEvents();
  }

  bindEvents() {
    this.$summary.addEventListener("click", this.onClickBind);
  }

  unbindEvents() {
    this.$summary.removeEventListener("click", this.onClickBind);
  }

  onClick(e) {
    e.preventDefault();

    this.$details.style.overflow = "hidden";

    if (this.isClosing || !this.$details.open) {
      this.open();
    } else if (this.isExpanding || this.$details.open) {
      this.shrink();
    }
  }

  getElementHeightWithMargins(element) {
    const style = window.getComputedStyle(element);
    const marginTop = parseFloat(style.marginTop);
    const marginBottom = parseFloat(style.marginBottom);
    return element.offsetHeight + marginTop + marginBottom;
  }


  shrink() {
    if (this.isClosing || !this.$details.open) return;

    this.isClosing = true;
    this.$details.classList.remove("is-active");

    const startHeight = `${this.getElementHeightWithMargins(this.$details)}px`;
    const endHeight = `${this.getElementHeightWithMargins(this.$summary)}px`;

    if (this.animation) this.animation.cancel();

    this.animation = this.$details.animate(
      { height: [startHeight, endHeight] },
      { duration: 300, easing: "cubic-bezier(0.165, 0.840, 0.440, 1.000)" }
    );

    this.animation.onfinish = () => {
      this.onAnimationFinish(false);
      if (currentOpenAccordion === this) currentOpenAccordion = null;
    };

    this.animation.oncancel = () => {
      this.isClosing = false;
      this.$details.classList.add("is-active");
    };

    this.onShrink?.(this.$details);

    this.$details.setAttribute('aria-expanded', false);
    this.$summary.setAttribute('aria-controls', this.$content.id);
  }

  open() {
    if (currentOpenAccordion && currentOpenAccordion !== this) {
      currentOpenAccordion.shrink();
    }

    this.$details.style.height = `${this.$details.offsetHeight}px`;
    this.$details.open = true;
    window.requestAnimationFrame(() => this.expand());
    currentOpenAccordion = this;

    this.onOpen?.(this.$details);

    this.$details.setAttribute('aria-expanded', true);
    this.$summary.setAttribute('aria-controls', this.$content.id);

  }


  expand() {
    this.isExpanding = true;
    this.$details.classList.add("is-active");

    if (this.$parent) this.$parent.classList.add("is-active");

    // const startHeight = `${this.$details.offsetHeight}px`;
    // const endHeight = `${this.$summary.offsetHeight + this.$content.offsetHeight}px`;

    const startHeight = `${this.getElementHeightWithMargins(this.$details)}px`;
    const endHeight = `${this.getElementHeightWithMargins(this.$summary) + this.getElementHeightWithMargins(this.$content)}px`;

    if (this.animation) {
      this.animation.cancel();
    }

    this.animation = this.$details.animate(
      {
        height: [startHeight, endHeight],
      },
      {
        duration: 300,
        easing: "cubic-bezier(0.165, 0.840, 0.440, 1.000)",
      }
    );

    this.animation.onfinish = () => this.onAnimationFinish(true);
    this.animation.oncancel = () => {
      this.isExpanding = false;
      this.$details.classList.remove("is-active");
    };
  }


  onAnimationFinish(open) {
    this.$details.open = open;
    this.animation = null;
    this.isClosing = false;
    this.isExpanding = false;
    this.$details.style.height = this.$details.style.overflow = "";

    if (!open && currentOpenAccordion === this) {
      currentOpenAccordion = null;
    }
  }

  setCallbacks({ onOpen = () => { }, onShrink = () => { } }) {
    this.onOpen = onOpen;
    this.onShrink = onShrink;
  }
}

// Capture the executing bundle origin: Webflow can load our local JS on its live domain.
const script = document.currentScript as HTMLScriptElement | null;
const origin = script?.src ? new URL(script.src).origin : window.location.origin;
const local = ["localhost", "127.0.0.1"].includes(new URL(origin).hostname);

export const url = (append = "api/agent") =>
  `${local ? "https://localhost:6545" : "https://aether-two-kappa.vercel.app"}/${append}`;

// Parse only known fields so incomplete streaming markers never appear in the UI.
export function parseAnswer(raw: string) {
  const parts = raw.split("|").map((part) => part.trim());
  const field = (tag: string, index: number) => {
    const part = parts[index] || "";
    return part.startsWith(tag) ? part.slice(tag.length).trim() :
      part.startsWith("(") ? "" : part;
  };
  const media = parts[3]?.match(/^(?:IMAGE|IMG|VIDEO)_(\d+)$/);
  return {
    title: field("(SH)", 0),
    short: field("(SR)", 1),
    long: field("(LR)", 2),
    media: media ? media[0].replace(/^IMG_/, "IMAGE_") : "IMAGE_9",
    CTA: /^CTA_[1-4]$/.test(parts[4] || "") ? parts[4] : "CTA_4",
  };
}

export async function readAnswer(response: Response, onUpdate: (text: string) => void) {
  if (!response.ok) throw new Error("API error");
  if (!response.headers.get("content-type")?.includes("application/x-ndjson")) {
    const data = await response.json();
    const text = data.result?.content?.[0]?.text?.value;
    if (typeof text !== "string" || !text.trim()) throw new Error("Missing answer");
    onUpdate(text);
    return text;
  }
  if (!response.body) throw new Error("Missing response stream");
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let text = "";
  let completed = false;
  const consume = (line: string) => {
    if (!line.trim()) return;
    const event = JSON.parse(line);
    if (event.type === "error") throw new Error(event.error);
    if (event.type === "done") completed = true;
    if (event.type === "delta" && typeof event.text === "string") {
      text += event.text;
      onUpdate(text);
    }
  };
  try {
    while (!completed) {
      const { value, done } = await reader.read();
      buffer += done ? decoder.decode() : decoder.decode(value, { stream: true });
      let newline;
      while ((newline = buffer.indexOf("\n")) !== -1) {
        consume(buffer.slice(0, newline));
        buffer = buffer.slice(newline + 1);
      }
      if (done) {
        if (buffer.trim()) consume(buffer);
        break;
      }
    }
    if (!completed || !text.trim()) throw new Error("The answer was interrupted");
    return text;
  } finally {
    await reader.cancel().catch(() => {});
    reader.releaseLock();
  }
}

interface EventMap<T = any> {
  [key: string]: ((data: T) => void)[];
}

class SimpleEmitter<T extends Record<string, any>> {
  private events: EventMap<T[keyof T]>;

  constructor() {
    this.events = {};
  }

  /**
   * Register an event handler for a given event.
   * @param {string} event - The name of the event.
   * @param {Function} handler - The callback function to handle the event.
   */
  on(event: string, handler: Function): void {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(handler as (data: any) => void);
  }

  /**
   * Unregister an event handler for a given event.
   * @param {string} event - The name of the event.
   * @param {Function} handler - The callback function to remove.
   */
  off(event: string, handler: Function): void {
    if (!this.events[event]) return;

    this.events[event] = this.events[event].filter((h) => h !== handler);
  }

  /**
   * Emit an event, calling all registered handlers.
   * @param {string} event - The name of the event.
   * @param {*} data - The data to pass to the event handlers.
   */
  emit(event: string, data: any): void {
    if (!this.events[event]) return;

    this.events[event].forEach((handler) => handler(data));
  }
}

interface StateObject {
  [key: string]: any;
}

class State {
  /**
   * @type {SimpleEmitter}
   * @static
   * @private
   */
  private static emitter: SimpleEmitter<StateObject> =
    new SimpleEmitter<StateObject>();

  /**
   * @type {Object}
   * @static
   * @private
   */
  private static state: StateObject = {};

  /**
   * Create a proxy for an object to enable nested reactivity.
   * @param {Object} obj - The object to create a proxy for.
   * @returns {Proxy} - The proxied object.
   * @private
   */
  private static createProxy(obj: object): any {
    return new Proxy(obj, {
      set: function (
        target: object,
        property: string | symbol,
        value: any,
        receiver: any
      ): boolean {
        State.emitter.emit(property.toString(), value);
        return Reflect.set(target, property, value, receiver);
      },
    });
  }

  /**
   * @type {Proxy}
   * @static
   * @private
   */
  private static proxy = new Proxy(State.state, {
    set: function (
      target: StateObject,
      property: string | symbol,
      value: any,
      receiver: any
    ): boolean {
      if (typeof value === "object" && value !== null) {
        value = State.createProxy(value);
      }
      State.emitter.emit(property.toString(), value);
      return Reflect.set(target, property, value, receiver);
    },
  });

  static getProxy(): any {
    return this.proxy;
  }

  /**
   * Register an event handler for a given event.
   * @param {string} event - The name of the event.
   * @param {Function} handler - The callback function to handle the event.
   */
  static on(event: string, handler: Function): void {
    this.emitter.on(event, handler);
  }

  /**
   * Unregister an event handler for a given event.
   * @param {string} event - The name of the event.
   * @param {Function} handler - The callback function to remove.
   */
  static off(event: string, handler: Function): void {
    this.emitter.off(event, handler);
  }
}

interface ProxyHandler<T extends object> {
  get(target: T, property: string | symbol): any;
  set(target: T, property: string | symbol, value: any, receiver: any): boolean;
}

const proxyHandler: ProxyHandler<ReturnType<typeof State.getProxy>> = {
  /**
   * Proxy handler to intercept property access.
   * @param {Object} target - The target object.
   * @param {string|symbol} property - The name of the property to get.
   * @returns {*} - The value of the property.
   */
  get(target: any, property: string | symbol): any {
    if (property in State) {
      return (State[property as keyof typeof State] as Function).bind(State);
    }
    return target[property];
  },

  /**
   * Proxy handler to intercept property setting.
   * @param {Object} target - The target object.
   * @param {string|symbol} property - The name of the property to set.
   * @param {*} value - The new value of the property.
   * @param {Object} receiver - The proxy or object that initially received the request.
   * @returns {boolean} - True if the property was set successfully, false otherwise.
   */
  set(
    target: any,
    property: string | symbol,
    value: any,
    receiver: any
  ): boolean {
    return Reflect.set(State.getProxy(), property, value, receiver);
  },
};

