const CLASS = {
    MODAL_OPEN: `has-modal-open`,
};

export class Modal extends Observe {
    static instance = null;

    constructor(element, aetherInstance) {
        super(element);

        if (Modal.instance) return Modal.instance;

        this.element = element;
        this.aether = aetherInstance;
        Modal.instance = this;

        this.init();

    }

    init() {
        // console.log("Initializing Modal...");

        this.$modal = this.element;
        this.$modalCloseWrapper = this.$modal?.querySelector('.modal__close-w');
        if (!this.$modal || !this.$modalCloseWrapper) return;

        gsap.set(this.$modal, { autoAlpha: 0, display: "none" });
        this.$modalCloseWrapper.onclick = () => this.close();

        this.anim = gsap.timeline({ paused: true })
            .set(this.$modal, { autoAlpha: 1, display: "flex" })
            .fromTo(this.$modal, {
                scale: 1.05,
                opacity: 0,
                filter: "blur(0.5rem)",
                transformOrigin: "center center",
            }, {
                duration: 0.8,
                ease: "expo.out",
                scale: 1,
                opacity: 1,
                filter: "blur(0px)",
            }, '<');

        this.closeBind = (e) => { if (e.key === "Escape") this.close(); };
        document.addEventListener('keyup', this.closeBind);
    }

    open() {
        html.classList.add(CLASS.MODAL_OPEN);
        // Scroll.stop();
        setTimeout(() => {
            this.anim.timeScale(1).play();
            const firstAccordion = document.querySelector('.accordion-w .accordion:first-child summary');
            firstAccordion?.click();
        }, 200);
    }

    close() {
        if (this.aether?.isSubmitting) {
            this.aether.requestDismissed = true;
            this.aether.requestController?.abort();
            this.aether.tlThinking?.kill();
            this.aether.responseWrapper.style.display = "none";
        }
        html.classList.remove(CLASS.MODAL_OPEN);
        this.anim.timeScale(1.2).reverse();
        this.closeAllAccordions();
        // Scroll.start();

        if (this.aether) {
            const originalContainer = document.querySelector(".main");
            const form = this.aether.form;

            gsap.to(form, {
                y: 40,
                opacity: 0,
                duration: 0.3,
                ease: "power2.in",
                onComplete: () => {
                    const flipState = Flip.getState(form, {
                        props: "width,height,borderRadius,opacity",
                        simple: true
                    });

                    originalContainer.appendChild(form);
                    Flip.from(flipState, {
                        duration: 0.8,
                        ease: "power2.inOut",
                        onStart: () => this.aether.transitionToState(this.aether.STATES.INITIAL),
                        onComplete: () => {
                            gsap.to(form, {
                                y: 0,
                                opacity: 1,
                                duration: 0.3,
                                ease: easePrimary
                            });
                        }
                    });
                }
            });
        }
    }

    toggle() {
        if (html.classList.contains(CLASS.MODAL_OPEN)) this.close();
        else this.open();
    }

    closeAllAccordions() {
        const accordions = document.querySelectorAll('.accordion-w .accordion');
        accordions.forEach(acc => acc.open = false);
    }

    destroy() {
        // console.log('Destroying Modal...');

        document.removeEventListener('keyup', this.closeBind);
        this.anim?.kill();
        Modal.instance = null;
    }


}

export class AetherDB {
  constructor(maxRecords = 10) {
    this.dbName = 'AetherResponses';
    this.storeName = 'conversations';
    this.maxRecords = maxRecords;
    this.db = null;
  }

  initializeDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, 1);

      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(this.storeName)) {
          const store = db.createObjectStore(this.storeName, { keyPath: 'id', autoIncrement: true });
          store.createIndex('byQuestion', 'question', { unique: false });
        }
      };

      request.onsuccess = (event) => {
        this.db = event.target.result;
        resolve(this.db);
      };

      request.onerror = (event) => {
        reject('IndexedDB error: ' + event.target.error);
      };
    });
  }

  async saveResponse(responseData) {
    if (!this.db) await this.initializeDB();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(this.storeName, 'readwrite');
      const store = transaction.objectStore(this.storeName);

      responseData.timestamp = responseData.timestamp || new Date().toISOString();

      const addRequest = store.add(responseData);

      addRequest.onsuccess = () => {
        this.enforceRecordLimit();
        resolve();
      };

      addRequest.onerror = (event) => reject(event.target.error);
    });
  }

  async enforceRecordLimit() {
    const allRecords = await this.getAllResponses();
    if (allRecords.length <= this.maxRecords) return;

    const sorted = allRecords.sort((a, b) =>
      new Date(a.timestamp) - new Date(b.timestamp));

    const deleteCount = allRecords.length - this.maxRecords;
    const recordsToDelete = sorted.slice(0, deleteCount);

    const transaction = this.db.transaction(this.storeName, 'readwrite');
    const store = transaction.objectStore(this.storeName);

    recordsToDelete.forEach(record => {
      store.delete(record.id);
    });
  }

  async getAllResponses() {
    if (!this.db) await this.initializeDB();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(this.storeName, 'readonly');
      const store = transaction.objectStore(this.storeName);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = (event) => reject(event.target.error);
    });
  }
}

import * as THREE from 'three'

import Gl from './Gl'

export default class Rendered {
  constructor() {
    this.gl = new Gl()

    this.instance = new THREE.WebGLRenderer({
      // canvas: this.gl.canvas,
      powerPreference: 'high-performance',
      // alpha: true,
      // antialias: true,
      precision: 'lowp',
    })

    this.instance.autoClear = false
    this.instance.setPixelRatio(this.gl.sizes.pixelRatio)
    this.instance.setSize(this.gl.sizes.width, this.gl.sizes.height)
    // this.instance.toneMapping = THREE.CineonToneMapping
    // this.instance.toneMappingExposure = 1
    this.instance.physicallyCorrectLights = true
    this.gl.canvas.appendChild(this.instance.domElement)
  }

  update() {
    for (const key in this.gl.world.scenes) {
      this.gl.world.scenes[key].renderPipeline()

      this.instance.clear()
    }

    // // // // // // // // // //
    this.instance.setRenderTarget(null)
    this.instance.render(this.gl.scene, this.gl.camera)
  }

  resize() {
    this.instance.setPixelRatio(this.gl.sizes.pixelRatio)
    this.instance.setSize(this.gl.sizes.width, this.gl.sizes.height)
  }
}

import * as THREE from 'three'

import Gl from '../../../Gl'

export default class ShaderPass {
  constructor(props) {
    this.gl = new Gl()

    this.props = props
    this.uniforms = this.props.material?.uniforms
  }

  init() {
    this.scene = new THREE.Scene()
    this.camera = new THREE.Camera()

    if (this.uniforms) {
      this.material = new THREE.RawShaderMaterial(this.props.material)
      this.geometry = new THREE.PlaneGeometry(2.0, 2.0)
      this.plane = new THREE.Mesh(this.geometry, this.material)
      this.scene.add(this.plane)
    }
  }

  update() {
    this.gl.renderer.instance.setRenderTarget(this.props.output)
    this.gl.renderer.instance.render(this.scene, this.camera)
    this.gl.renderer.instance.setRenderTarget(null)
  }
}

import ShaderPass from './ShaderPass'

import * as THREE from 'three'

export default class Advection extends ShaderPass {
  constructor(simProps) {
    super({
      material: {
        vertexShader: /* glsl */ `
          attribute vec3 position;
          uniform vec2 px;
          uniform vec2 boundarySpace;
          varying vec2 uv;

          precision highp float;

          void main(){
              vec3 pos = position;
              vec2 scale = 1.0 - boundarySpace * 2.0;
              pos.xy = pos.xy * scale;
              uv = vec2(0.5)+(pos.xy)*0.5;
              gl_Position = vec4(pos, 1.0);
          }

        `,
        fragmentShader: /* glsl */ `
          precision highp float;
          uniform sampler2D velocity;
          uniform float dt;
          uniform float dissipation;
          uniform bool isBFECC;
          // uniform float uvScale;
          uniform vec2 fboSize;
          uniform vec2 px;
          varying vec2 uv;

          void main(){
              vec2 ratio = max(fboSize.x, fboSize.y) / fboSize;

              if(isBFECC == false){
                  vec2 vel = texture2D(velocity, uv).xy;
                  vec2 uv2 = uv - vel * dt * ratio;
                  vec2 newVel = texture2D(velocity, uv2).xy * dissipation;
                  gl_FragColor = vec4(newVel, 0.0, 0.0);
              } else {
                  vec2 spot_new = uv;
                  vec2 vel_old = texture2D(velocity, uv).xy;
                  // back trace
                  vec2 spot_old = spot_new - vel_old * dt * ratio;
                  vec2 vel_new1 = texture2D(velocity, spot_old).xy;

                  // forward trace
                  vec2 spot_new2 = spot_old + vel_new1 * dt * ratio;

                  vec2 error = spot_new2 - spot_new;

                  vec2 spot_new3 = spot_new - error / 2.0;
                  vec2 vel_2 = texture2D(velocity, spot_new3).xy;

                  // back trace 2
                  vec2 spot_old2 = spot_new3 - vel_2 * dt * ratio;
                  // gl_FragColor = vec4(spot_old2, 0.0, 0.0);
                  vec2 newVel2 = texture2D(velocity, spot_old2).xy * dissipation; 
                  gl_FragColor = vec4(newVel2, 0.0, 0.0);
              }
          }

        `,
        uniforms: {
          boundarySpace: {
            value: simProps.cellScale,
          },
          px: {
            value: simProps.cellScale,
          },
          fboSize: {
            value: simProps.fboSize,
          },
          velocity: {
            value: simProps.src.texture,
          },
          dt: {
            value: simProps.dt,
          },
          isBFECC: {
            value: true,
          },
          dissipation: {
            value: simProps.dissipation,
          },
        },
      },
      output: simProps.dst,
    })

    this.init()
  }

  init() {
    super.init()
    this.createBoundary()
  }

  createBoundary() {
    const boundaryG = new THREE.BufferGeometry()
    const vertices_boundary = new Float32Array([
      // left
      -1, -1, 0, -1, 1, 0,

      // top
      -1, 1, 0, 1, 1, 0,

      // right
      1, 1, 0, 1, -1, 0,

      // bottom
      1, -1, 0, -1, -1, 0,
    ])
    boundaryG.setAttribute('position', new THREE.BufferAttribute(vertices_boundary, 3))

    const boundaryM = new THREE.RawShaderMaterial({
      vertexShader: /* glsl */ `
        attribute vec3 position;
        varying vec2 uv;
        uniform vec2 px;


        precision highp float;

        void main(){
            vec3 pos = position;
            uv = 0.5 + pos.xy * 0.5;
            vec2 n = sign(pos.xy);
            pos.xy = abs(pos.xy) - px * 1.0;
            pos.xy *= n;
            gl_Position = vec4(pos, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        precision highp float;
        uniform sampler2D velocity;
        uniform float dt;
        uniform float dissipation;
        uniform bool isBFECC;
        // uniform float uvScale;
        uniform vec2 fboSize;
        uniform vec2 px;
        varying vec2 uv;

        void main(){
            vec2 ratio = max(fboSize.x, fboSize.y) / fboSize;

            if(isBFECC == false){
                vec2 vel = texture2D(velocity, uv).xy;
                vec2 uv2 = uv - vel * dt * ratio;
                vec2 newVel = texture2D(velocity, uv2).xy;
                gl_FragColor = vec4(newVel, 0.0, 0.0);
            } else {
                vec2 spot_new = uv;
                vec2 vel_old = texture2D(velocity, uv).xy;
                // back trace
                vec2 spot_old = spot_new - vel_old * dt * ratio;
                vec2 vel_new1 = texture2D(velocity, spot_old).xy;

                // forward trace
                vec2 spot_new2 = spot_old + vel_new1 * dt * ratio;

                vec2 error = spot_new2 - spot_new;

                vec2 spot_new3 = spot_new - error / 2.0;
                vec2 vel_2 = texture2D(velocity, spot_new3).xy;

                // back trace 2
                vec2 spot_old2 = spot_new3 - vel_2 * dt * ratio;
                // gl_FragColor = vec4(spot_old2, 0.0, 0.0);
                vec2 newVel2 = texture2D(velocity, spot_old2).xy * dissipation; 
                gl_FragColor = vec4(newVel2, 0.0, 0.0);
            }
        }

      `,
      uniforms: this.uniforms,
    })

    this.line = new THREE.LineSegments(boundaryG, boundaryM)
    this.scene.add(this.line)
  }

  update({ dt, isBounce, BFECC }) {
    this.uniforms.dt.value = dt
    this.line.visible = isBounce
    this.uniforms.isBFECC.value = BFECC

    super.update()
  }
}

import * as THREE from 'three'

import Gl from '../../../Gl'

export default class Mouse {
  constructor() {
    this.gl = new Gl()

    this.mouseMoved = false
    this.touching = false
    this.previousTouching = false
    this.coords = new THREE.Vector2()
    this.coords_old = new THREE.Vector2()
    this.diff = new THREE.Vector2()
    this.timer = null
    this.count = 0
  }

  init() {
    document.body.addEventListener('mousemove', this.onDocumentMouseMove.bind(this), false)
    document.body.addEventListener('touchstart', this.onDocumentTouchStart.bind(this), false)
    document.body.addEventListener('touchend', this.onDocumentTouchEnd.bind(this), false)
    document.body.addEventListener('touchmove', this.onDocumentTouchMove.bind(this), false)
  }

  setCoords(x, y) {
    if (this.timer) clearTimeout(this.timer)
    this.coords.set(x, y)

    this.mouseMoved = true
    this.timer = setTimeout(() => {
      this.mouseMoved = false
    }, 100)
  }

  onDocumentMouseMove(event) {
    this.setCoords(this.gl.mouse.normalized.current.x, this.gl.mouse.normalized.current.y)
  }

  onDocumentTouchStart(event) {
    this.touching = true
  }

  onDocumentTouchEnd(event) {
    this.touching = false
  }

  onDocumentTouchMove(event) {
    if (event.touches.length === 1) {
      // event.preventDefault();

      this.setCoords(this.gl.mouse.normalized.current.x, this.gl.mouse.normalized.current.y)
    }
  }

  update() {
    /* 
      Touch
    */
    if (this.touching != this.previousTouching) {
      // Reset touch when started to prevent
      if (this.touching) {
        this.coords.copy(this.gl.mouse.normalized.current)
        this.coords_old.copy(this.gl.mouse.normalized.current)
      }
    }

    /* 
      Calculate diff
    */
    this.diff.subVectors(this.coords, this.coords_old)

    this.coords_old.copy(this.coords)

    if (this.coords_old.x === 0 && this.coords_old.y === 0) this.diff.set(0, 0)

    this.previousTouching = this.touching
  }
}

import ShaderPass from './ShaderPass'
import Mouse from './Mouse'

import * as THREE from 'three'

export default class ExternalForce extends ShaderPass {
  constructor(simProps) {
    super({
      output: simProps.dst,
    })

    this.mouse = new Mouse()
    this.mouse.init()

    this.init(simProps)
  }

  init(simProps) {
    super.init()
    const mouseG = new THREE.PlaneGeometry(1, 1)

    this.mouseMaterial = new THREE.RawShaderMaterial({
      vertexShader: /* glsl */ `
        precision highp float;

        attribute vec3 position;
        attribute vec2 uv;
        uniform vec2 center;
        uniform vec2 scale;
        uniform vec2 px;
        varying vec2 vUv;

        void main(){
            vec2 pos = position.xy * scale * 2.0 * px + center;
            vUv = uv;
            gl_Position = vec4(pos, 0.0, 1.0);
        }

      `,
      fragmentShader: /* glsl */ `
        precision highp float;

        uniform vec2 force;
        uniform vec2 center;
        uniform vec2 scale;
        uniform vec2 px;
        varying vec2 vUv;

        void main(){
            vec2 circle = (vUv - 0.5) * 2.0;
            float d = 1.0-min(length(circle), 1.0);
            d *= d;
            gl_FragColor = vec4(force * d, 0, 1);
        }

      `,
      blending: THREE.AdditiveBlending,
      uniforms: {
        px: {
          value: simProps.cellScale,
        },
        force: {
          value: new THREE.Vector2(0.0, 0.0),
        },
        center: {
          value: new THREE.Vector2(0.0, 0.0),
        },
        scale: {
          value: new THREE.Vector2(simProps.cursor_size, simProps.cursor_size),
        },
      },
    })

    this.mouseMesh = new THREE.Mesh(mouseG, this.mouseMaterial)
    this.scene.add(this.mouseMesh)
  }

  update(props) {
    this.mouse.update()

    const forceX = (this.mouse.diff.x / 2) * props.mouse_force
    const forceY = (this.mouse.diff.y / 2) * props.mouse_force

    // console.log(props.cursor_size)

    const cursorSizeX = props.cursor_size * props.cellScale.x
    const cursorSizeY = props.cursor_size * props.cellScale.y

    const centerX = Math.min(Math.max(this.mouse.coords.x, -1 + cursorSizeX + props.cellScale.x * 2), 1 - cursorSizeX - props.cellScale.x * 2)
    const centerY = Math.min(Math.max(this.mouse.coords.y, -1 + cursorSizeY + props.cellScale.y * 2), 1 - cursorSizeY - props.cellScale.y * 2)

    const uniforms = this.mouseMesh.material.uniforms

    uniforms.force.value.set(forceX, forceY)
    uniforms.center.value.set(centerX, centerY)
    uniforms.scale.value.set(props.cursor_size, props.cursor_size)

    super.update()
  }
}

import ShaderPass from './ShaderPass'

export default class Viscous extends ShaderPass {
  constructor(simProps) {
    super({
      material: {
        vertexShader: /* glsl */ `
          attribute vec3 position;
          uniform vec2 px;
          uniform vec2 boundarySpace;
          varying vec2 uv;

          precision highp float;

          void main(){
              vec3 pos = position;
              vec2 scale = 1.0 - boundarySpace * 2.0;
              pos.xy = pos.xy * scale;
              uv = vec2(0.5)+(pos.xy)*0.5;
              gl_Position = vec4(pos, 1.0);
          }
        `,
        fragmentShader: /* glsl */ `
          precision highp float;
          uniform sampler2D velocity;
          uniform sampler2D velocity_new;
          uniform float v;
          uniform vec2 px;
          uniform float dt;

          varying vec2 uv;

          void main(){
              // poisson equation
              vec2 old = texture2D(velocity, uv).xy;
              vec2 new0 = texture2D(velocity_new, uv + vec2(px.x * 2.0, 0)).xy;
              vec2 new1 = texture2D(velocity_new, uv - vec2(px.x * 2.0, 0)).xy;
              vec2 new2 = texture2D(velocity_new, uv + vec2(0, px.y * 2.0)).xy;
              vec2 new3 = texture2D(velocity_new, uv - vec2(0, px.y * 2.0)).xy;

              vec2 new = 4.0 * old + v * dt * (new0 + new1 + new2 + new3);
              new /= 4.0 * (1.0 + v * dt);

              gl_FragColor = vec4(new, 0.0, 0.0);
          }

        `,
        uniforms: {
          boundarySpace: {
            value: simProps.boundarySpace,
          },
          velocity: {
            value: simProps.src.texture,
          },
          velocity_new: {
            value: simProps.dst_.texture,
          },
          v: {
            value: simProps.viscous,
          },
          px: {
            value: simProps.cellScale,
          },
          dt: {
            value: simProps.dt,
          },
        },
      },

      output: simProps.dst,

      output0: simProps.dst_,
      output1: simProps.dst,
    })

    this.init()
  }

  update({ viscous, iterations, dt }) {
    let fbo_in, fbo_out
    this.uniforms.v.value = viscous
    for (var i = 0; i < iterations; i++) {
      if (i % 2 == 0) {
        fbo_in = this.props.output0
        fbo_out = this.props.output1
      } else {
        fbo_in = this.props.output1
        fbo_out = this.props.output0
      }

      this.uniforms.velocity_new.value = fbo_in.texture
      this.props.output = fbo_out
      this.uniforms.dt.value = dt

      super.update()
    }

    return fbo_out
  }
}

import ShaderPass from './ShaderPass'

export default class Divergence extends ShaderPass {
  constructor(simProps) {
    super({
      material: {
        vertexShader: /* glsl */ `
          attribute vec3 position;
          uniform vec2 px;
          uniform vec2 boundarySpace;
          varying vec2 uv;

          precision highp float;

          void main(){
              vec3 pos = position;
              vec2 scale = 1.0 - boundarySpace * 2.0;
              pos.xy = pos.xy * scale;
              uv = vec2(0.5)+(pos.xy)*0.5;
              gl_Position = vec4(pos, 1.0);
          }

        `,
        fragmentShader: /* glsl */ `
          precision highp float;
          uniform sampler2D velocity;
          uniform float dt;
          uniform vec2 px;
          varying vec2 uv;

          void main(){
              float x0 = texture2D(velocity, uv-vec2(px.x, 0)).x;
              float x1 = texture2D(velocity, uv+vec2(px.x, 0)).x;
              float y0 = texture2D(velocity, uv-vec2(0, px.y)).y;
              float y1 = texture2D(velocity, uv+vec2(0, px.y)).y;
              float divergence = (x1-x0 + y1-y0) / 2.0;

              gl_FragColor = vec4(divergence / dt);
          }

        `,
        uniforms: {
          boundarySpace: {
            value: simProps.boundarySpace,
          },
          velocity: {
            value: simProps.src.texture,
          },
          px: {
            value: simProps.cellScale,
          },
          dt: {
            value: simProps.dt,
          },
        },
      },
      output: simProps.dst,
    })

    this.init()
  }

  update({ vel }) {
    this.uniforms.velocity.value = vel.texture
    super.update()
  }
}

import ShaderPass from './ShaderPass'

export default class Divergence extends ShaderPass {
  constructor(simProps) {
    super({
      material: {
        vertexShader: /* glsl */ `
          attribute vec3 position;
          uniform vec2 px;
          uniform vec2 boundarySpace;
          varying vec2 uv;

          precision highp float;

          void main(){
              vec3 pos = position;
              vec2 scale = 1.0 - boundarySpace * 2.0;
              pos.xy = pos.xy * scale;
              uv = vec2(0.5)+(pos.xy)*0.5;
              gl_Position = vec4(pos, 1.0);
          }

        `,
        fragmentShader: /* glsl */ `
          precision highp float;
          uniform sampler2D pressure;
          uniform sampler2D divergence;
          uniform float straightness;
          uniform vec2 px;
          varying vec2 uv;

          void main(){    
              // poisson equation
              float p0 = texture2D(pressure, uv+vec2(px.x * 2.0,  0)).r;
              float p1 = texture2D(pressure, uv-vec2(px.x * 2.0, 0)).r;
              float p2 = texture2D(pressure, uv+vec2(0, px.y * 2.0 )).r;
              float p3 = texture2D(pressure, uv-vec2(0, px.y * 2.0 )).r;
              float div = texture2D(divergence, uv).r;

              float newP = (p0 + p1 + p2 + p3) / (4.0 + straightness) - div;
              gl_FragColor = vec4(newP);
          }

        `,
        uniforms: {
          boundarySpace: {
            value: simProps.boundarySpace,
          },
          pressure: {
            value: simProps.dst_.texture,
          },
          divergence: {
            value: simProps.src.texture,
          },
          px: {
            value: simProps.cellScale,
          },
          straightness: {
            value: simProps.straightness,
          },
        },
      },
      output: simProps.dst,

      output0: simProps.dst_,
      output1: simProps.dst,
    })

    this.init()
  }

  update({ iterations }) {
    let p_in, p_out

    for (var i = 0; i < iterations; i++) {
      if (i % 2 == 0) {
        p_in = this.props.output0
        p_out = this.props.output1
      } else {
        p_in = this.props.output1
        p_out = this.props.output0
      }

      this.uniforms.pressure.value = p_in.texture
      this.props.output = p_out
      super.update()
    }

    return p_out
  }
}

import ShaderPass from './ShaderPass'

export default class Divergence extends ShaderPass {
  constructor(simProps) {
    super({
      material: {
        vertexShader: /* glsl */ `
          attribute vec3 position;
          uniform vec2 px;
          uniform vec2 boundarySpace;
          varying vec2 uv;

          precision highp float;

          void main(){
              vec3 pos = position;
              vec2 scale = 1.0 - boundarySpace * 2.0;
              pos.xy = pos.xy * scale;
              uv = vec2(0.5)+(pos.xy)*0.5;
              gl_Position = vec4(pos, 1.0);
          }

        `,
        fragmentShader: /* glsl */ `
          precision highp float;
          uniform sampler2D pressure;
          uniform sampler2D velocity;
          uniform vec2 px;
          uniform float dt;
          varying vec2 uv;

          void main(){
              float step = 1.0;

              float p0 = texture2D(pressure, uv+vec2(px.x * step, 0)).r;
              float p1 = texture2D(pressure, uv-vec2(px.x * step, 0)).r;
              float p2 = texture2D(pressure, uv+vec2(0, px.y * step)).r;
              float p3 = texture2D(pressure, uv-vec2(0, px.y * step)).r;

              vec2 v = texture2D(velocity, uv).xy;
              vec2 gradP = vec2(p0 - p1, p2 - p3) * 0.5;
              v = v - gradP * dt;
              gl_FragColor = vec4(v, 0.0, 1.0);
          }

        `,
        uniforms: {
          boundarySpace: {
            value: simProps.boundarySpace,
          },
          pressure: {
            value: simProps.src_p.texture,
          },
          velocity: {
            value: simProps.src_v.texture,
          },
          px: {
            value: simProps.cellScale,
          },
          dt: {
            value: simProps.dt,
          },
        },
      },
      output: simProps.dst,
    })

    this.init()
  }

  update({ vel, pressure }) {
    this.uniforms.velocity.value = vel.texture
    this.uniforms.pressure.value = pressure.texture
    super.update()
  }
}

import * as THREE from 'three'

import Advection from './Advection'
import ExternalForce from './ExternalForce'
import Viscous from './Viscous'
import Divergence from './Divergence'
import Poisson from './Poisson'
import Pressure from './Pressure'
import Gl from '../../../Gl'

export default class Simulation {
  constructor(props) {
    this.gl = new Gl()

    this.props = props

    this.fbos = {
      vel_0: null,
      vel_1: null,

      // for calc next velocity with viscous
      vel_viscous0: null,
      vel_viscous1: null,

      // for calc pressure
      div: null,

      // for calc poisson equation
      pressure_0: null,
      pressure_1: null,
    }

    this.options = {
      iterations_poisson: 2,
      iterations_viscous: 2,
      dissipation: 0.96,
      mouse_force: 50,
      resolution: 0.075,
      cursor_size: 10,
      straightness: 1.0,
      viscous: 30,
      isBounce: false,
      dt: 0.014,
      isViscous: false,
      BFECC: false,
    }

    // const controls = new Controls(this.options);

    this.fboSize = new THREE.Vector2()
    this.cellScale = new THREE.Vector2()
    this.boundarySpace = new THREE.Vector2()

    this.init()
  }

  init() {
    this.calcSize()
    this.createAllFBO()
    this.createShaderPass()
  }

  createAllFBO() {
    const type = /(iPad|iPhone|iPod)/g.test(navigator.userAgent) ? THREE.HalfFloatType : THREE.FloatType

    for (let key in this.fbos) {
      this.fbos[key] = new THREE.WebGLRenderTarget(this.fboSize.x, this.fboSize.y, {
        type: type,
      })
    }
  }

  createShaderPass() {
    this.advection = new Advection({
      cellScale: this.cellScale,
      fboSize: this.fboSize,
      dt: this.options.dt,
      src: this.fbos.vel_0,
      dst: this.fbos.vel_1,
      dissipation: this.options.dissipation,
    })

    this.externalForce = new ExternalForce({
      cellScale: this.cellScale,
      cursor_size: this.options.cursor_size,
      dst: this.fbos.vel_1,
    })

    this.viscous = new Viscous({
      cellScale: this.cellScale,
      boundarySpace: this.boundarySpace,
      viscous: this.options.viscous,
      src: this.fbos.vel_1,
      dst: this.fbos.vel_viscous1,
      dst_: this.fbos.vel_viscous0,
      dt: this.options.dt,
    })

    this.divergence = new Divergence({
      cellScale: this.cellScale,
      boundarySpace: this.boundarySpace,
      src: this.fbos.vel_viscous0,
      dst: this.fbos.div,
      dt: this.options.dt,
    })

    this.poisson = new Poisson({
      cellScale: this.cellScale,
      boundarySpace: this.boundarySpace,
      straightness: this.options.straightness,
      src: this.fbos.div,
      dst: this.fbos.pressure_1,
      dst_: this.fbos.pressure_0,
    })

    this.pressure = new Pressure({
      cellScale: this.cellScale,
      boundarySpace: this.boundarySpace,
      src_p: this.fbos.pressure_0,
      src_v: this.fbos.vel_viscous0,
      dst: this.fbos.vel_0,
      dt: this.options.dt,
    })
  }

  calcSize() {
    const width = Math.round(this.options.resolution * this.gl.sizes.width)
    const height = Math.round(this.options.resolution * this.gl.sizes.height)

    let px_x = 1.0 / width
    let px_y = 1.0 / height

    if (width > 1100 * this.options.resolution) {
      px_x *= width / (1100 * this.options.resolution)
      px_y *= width / (1100 * this.options.resolution)
    } else {
      const slowedScale = 1 - (1 - width / (1100 * this.options.resolution)) * 0.5

      px_x *= slowedScale
      px_y *= slowedScale
    }

    this.cellScale.set(px_x, px_y)
    this.fboSize.set(width, height)
  }

  resize() {
    this.calcSize()

    for (let key in this.fbos) {
      this.fbos[key].setSize(this.fboSize.x, this.fboSize.y)
    }
  }

  update() {
    if (this.options.isBounce) {
      this.boundarySpace.set(0, 0)
    } else {
      this.boundarySpace.copy(this.cellScale)
    }

    this.advection.update(this.options)

    this.externalForce.update({
      cursor_size: this.options.cursor_size,
      mouse_force: this.options.mouse_force,
      cellScale: this.cellScale,
    })

    let vel = this.fbos.vel_1

    if (this.options.isViscous) {
      vel = this.viscous.update({
        viscous: this.options.viscous,
        iterations: this.options.iterations_viscous,
        dt: this.options.dt,
      })
    }

    this.divergence.update({ vel })

    const pressure = this.poisson.update({
      iterations: this.options.iterations_poisson,
    })

    this.pressure.update({ vel, pressure })
  }
}

import * as THREE from 'three'
import Gl from '../../Gl'

import Simulation from './classes/Simulation'
import Mouse from './classes/Mouse'

export default class FluidCursor {
  constructor() {
    this.gl = new Gl()

    this.simulation = new Simulation()
    this.mouse = new Mouse()
    this.mouse.init()

    this.scene = new THREE.Scene()
    this.camera = new THREE.Camera()

    this.output = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.RawShaderMaterial({
        vertexShader: /* glsl */ `
          attribute vec3 position;
          uniform vec2 px;
          uniform vec2 boundarySpace;
          varying vec2 uv;

          precision highp float;

          void main() {
            vec3 pos = position;
            vec2 scale = 1.0 - boundarySpace * 2.0;
            pos.xy = pos.xy * scale;
            uv = vec2(0.5)+(pos.xy)*0.5;
            gl_Position = vec4(pos, 1.0);
          }
        `,
        fragmentShader: /* glsl */ `
          precision highp float;
          uniform sampler2D velocity;
          varying vec2 uv;
          uniform vec2 uMouse;

          void main(){
              vec2 uvScaled = uv * 1.5 - (uMouse * 0.25 + 0.25);

              vec2 vel = texture2D(velocity, uv).xy;
              float len = length(vel);
              vel = vel * 0.5 + 0.5;

              vec3 color = vec3(vel.x, vel.y, 1.0);
              color = mix(vec3(1.0), color, len);

              float mask = min(smoothstep(0.0, 0.25, uvScaled.x), smoothstep(1.0, 0.75, uvScaled.x));
              mask *= min(smoothstep(0.0, 0.25, uvScaled.y), smoothstep(1.0, 0.75, uvScaled.y));

              gl_FragColor = vec4((1.0 - color), 1.0);
          }
        `,
        uniforms: {
          velocity: {
            value: this.simulation.fbos.vel_0.texture,
          },
          uMouse: new THREE.Uniform(new THREE.Vector2(0.0, 0.0)),
          boundarySpace: {
            value: new THREE.Vector2(),
          },
        },
      })
    )

    this.scene.add(this.output)

    /* 
      Render Targets
    */
    this.sourceTarget = new THREE.RenderTarget(this.gl.sizes.width, this.gl.sizes.height, {
      samples: 1,
    })

    /* 
      Frame-rate limit
    */
    this.clock = new THREE.Clock()
    this.delta = 0
    this.interval = 1 / 60

    // this.update()
  }

  resize() {
    this.simulation.resize()
  }

  update() {
    // requestAnimationFrame(this.update.bind(this))
    this.delta += this.clock.getDelta()

    if (this.delta > this.interval) {
      this.mouse.update()
      this.simulation.update()

      this.gl.renderer.instance.setRenderTarget(this.sourceTarget)
      this.gl.renderer.instance.render(this.scene, this.camera)

      this.delta = this.delta % this.interval

      this.output.material.uniforms.uMouse.value = this.gl.world.mouse.eased.fresnel.value
    }
  }
}

