    this.uniforms.uTime.value = this.gl.time.elapsed * 0.5
  }
}

import * as THREE from 'three'
import gsap from '@/gsap'
import Gl from '@/gl/Gl'

export default class Waves {
  constructor() {
    this.gl = new Gl()

    /* 
      Instance
    */
    this.instance = new THREE.Group()

    /* 
      Flags
    */
    this.isAnimating = false

    /* 
      Global
    */
    this.globalSpeed = 1.0

    /* 
      Solid
    */
    this.geometry = new THREE.PlaneGeometry(30, 30, 256, 256)
    this.material = new THREE.ShaderMaterial({
      transparent: true,
      // wireframe: true,
      uniforms: {
        uTime: new THREE.Uniform(0.0),
        uWaveTransition: new THREE.Uniform(0.0),
        uLightIntensity: new THREE.Uniform(1.0),
        uIntensity: new THREE.Uniform(1.0),
        uFrequency: new THREE.Uniform(1.0),
        uLightDirection: new THREE.Uniform(new THREE.Vector3(3.0, 3.0, -1.0)),

        tNoise: new THREE.Uniform(this.gl.assets.textures.noise),

        COLOR_BASE: new THREE.Uniform(new THREE.Color(0x133153)),
        COLOR_HIGHLIGHT: new THREE.Uniform(new THREE.Color(0x32526f)),
        COLOR_LIGHT: new THREE.Uniform(new THREE.Color(0x60b2ff)),
      },
      vertexShader: /* glsl */ `
        #include <orthogonal>

        varying vec2 vUv;
        varying vec2 vUvn;
        varying vec3 vNormal;
        varying float vLight;
        varying float vTransitionLight;
        varying float vTransitionMask;
        varying float vWave;
        varying float vBigWave;

        uniform float uTime;
        uniform float uWaveTransition;
        uniform float uIntensity;
        uniform float uFrequency;
        uniform vec3 uLightDirection;

        uniform sampler2D tNoise;

        const float TRANSITION_SIZE = 2.;
        const float WAVE_STRENGTH = 6.;
        const float LIGHT_WIDTH = 2.0;

        #include <getSmallWave>
        #include <getBigWave>

        void main() {
          vec2 uvN = uv * 2.0 - 1.0;

          /* 
            Texture Noise
          */
          float textureNoise = 1.0 - texture2D(tNoise, uvN * 2.0).r * 2.0;

          /* 
            Light
          */
          vec3 center = position;
          vec3 neighbourX = position + vec3(0.01, 0.0, 0.0);
          vec3 neighbourY = position + vec3(0.0, -0.01, 0.0);

          float bigWave = getBigWave(position) * uIntensity;

          center.z += getSmallWaves(position, textureNoise) + bigWave;
          neighbourX.z += getSmallWaves(neighbourX, textureNoise) + getBigWave(neighbourX) * uIntensity;
          neighbourY.z += getSmallWaves(neighbourY, textureNoise) + getBigWave(neighbourY) * uIntensity;

          vec3 dx = neighbourX - center;
          vec3 dy = neighbourY - center;


          /* 
            Transition wave
          */
          float localPosition = length(position) * 0.5;
          float transitionMask = length(position.x + position.y * 0.25);
          float transitionLight = max(1.0 - distance(localPosition, smoothstep(0.2, 1.0, uWaveTransition) * 5.5) * (LIGHT_WIDTH + (1.0 - smoothstep(0.2, 1.0, uWaveTransition))), 0.0);

          gl_Position = projectionMatrix * viewMatrix * modelMatrix * vec4(center, 1.0);

          /* 
            Varyings
          */
          vTransitionMask = transitionMask;
          vNormal = 1.0 - normalize(cross(dx, dy));

          vUv = uv;
          vUvn = uvN;
          vLight = max(dot(vNormal, uLightDirection), 0.0);
          vTransitionLight = transitionLight;
          vWave = center.z;
          vBigWave = bigWave;
        }
      `,
      fragmentShader: /* glsl */ `
        varying vec2 vUv;
        varying vec2 vUvn;
        varying vec3 vNormal;
        varying float vLight;
        varying float vTransitionLight;
        varying float vTransitionMask;
        varying float vWave;
        varying float vBigWave;

        uniform float uWaveTransition;
        uniform float uLightIntensity;
        uniform vec3 COLOR_BASE;
        uniform vec3 COLOR_HIGHLIGHT;
        uniform vec3 COLOR_LIGHT;

        void main() {
          float alpha = smoothstep(1.0, 0.5, length(vUvn));
          float centerShadow = smoothstep(0.0, 0.5, length(vUvn));
          float vignette = smoothstep(0.25, 0.75, length(vUvn));
          float centerHighlight = smoothstep(0.0, 0.25, length(vUvn));

          /* 
            Transition Wave
          */
          // transitionWave += pow(vTransition, 2.0);
          // transitionWave *= 1.0 - pow(uWaveTransition, 4.0);

          vec3 color = mix(COLOR_BASE, COLOR_HIGHLIGHT, vLight);
          color += vec3(0.5, 0.75, 1.0) * pow((1.0 - distance(vUv, vec2(0.85, 1.0))) * 4.0, 4.0) * 0.01; // Side Highlight
          color *= min(pow(distance(vUv, vec2(0.0)) * 1.5, 6.0), 1.0); // Side Shadow
          color *= centerShadow; // Center Shadow
          // color *= centerHighlight; // Center shadow
          // color = mix(color, COLOR_LIGHT, (1.0 - centerHighlight) * sin(smoothstep(0.0, 0.25, uWaveTransition) * 3.14) ); // Center Highlight
          color = mix(color, COLOR_BASE, vignette); // Fading on sides
          color *= clamp(vLight * 0.3, 0.0, 1.0); // Contrast
          color *= 1.0 - clamp(vBigWave, 0.0, 1.0) * 0.25; // Big wave highlight
          color = mix(color, COLOR_LIGHT, vTransitionLight * smoothstep(1.0, 0.75, uWaveTransition) * smoothstep(0.0, 0.05, uWaveTransition) * uLightIntensity); // Light transition
          color += smoothstep(0.5, 1.0,vTransitionLight) * 1.25 * smoothstep(1.0, 0.75, uWaveTransition) * smoothstep(0.0, 0.05, uWaveTransition) * smoothstep(3.0, 6., vTransitionMask) * uLightIntensity; // Bright light transition highlight
          color = min(color, 0.65); // Prevent very bright light 

          gl_FragColor = vec4(color, alpha);

          // gl_FragColor = vec4(vec3(clamp(vLight * 0.4, 0.0, 1.0)), alpha);
        }
      `,
    })

    this.mesh = new THREE.Mesh(this.geometry, this.material)
    this.mesh.rotation.x = -Math.PI * 0.425
    this.mesh.position.set(0.114, 1.82 - 4, -0.48 - 1.5)
    this.mesh.renderOrder = 1

    this.instance.add(this.mesh)

    /* 
      Wireframe
    */
    this.wireframeMaterial = new THREE.ShaderMaterial({
      transparent: true,
      wireframe: true,
      uniforms: this.material.uniforms,
      depthTest: false,
      vertexShader: /* glsl */ `
        #include <orthogonal>

        varying vec2 vUv;
        varying float vTransitionLight;
        varying float vTransitionMask;
        varying float vWave;

        uniform float uTime;
        uniform float uWaveTransition;     
        uniform float uIntensity;
        uniform float uFrequency;

        uniform sampler2D tNoise;

        const float TRANSITION_SIZE = 2.;
        const float WAVE_STRENGTH = 6.;
        const float LIGHT_WIDTH = 1.0;

        #include <getSmallWave>
        #include <getBigWave>

        void main() {
          /* 
            Texture Noise
          */
          // float textureNoise = texture2D(tNoise, vUv).r;

          /* 
            Light
          */
          vec3 center = position;
          center.z += getSmallWaves(position, 0.0) + getBigWave(position) * uIntensity;

          /* 
            Transition wave
          */
          float localPosition = length(position) * 0.5;
          float transitionMask = length(position.x + position.y * 0.25);
          float transitionLight = max(1.0 - distance(localPosition, smoothstep(0.2, 1.0, uWaveTransition) * 5.5) * (1.0 + (LIGHT_WIDTH - smoothstep(0.2, 1.0, uWaveTransition))), 0.0);

          gl_Position = projectionMatrix * viewMatrix * modelMatrix * vec4(center, 1.0);

          /* 
            Varyings
          */
          vTransitionMask = transitionMask;
          vUv = uv;
          vTransitionLight = transitionLight;
          vWave = center.z;

        }
      `,
      fragmentShader: /* glsl */ `
        varying vec2 vUv;
        varying float vTransitionLight;

        uniform float uWaveTransition;
        uniform float uLightIntensity;
        uniform vec3 COLOR_LIGHT;

        void main() {        
          gl_FragColor = vec4(COLOR_LIGHT * 1.75, vTransitionLight * sin(smoothstep(0.4, 0.75, uWaveTransition) * 3.14) * uLightIntensity);
          gl_FragColor.rgb = min(gl_FragColor.rgb, 0.65);
        }
      `,
    })

    this.wireframeMesh = new THREE.Mesh(new THREE.PlaneGeometry(30, 30, 54, 54), this.wireframeMaterial)
    this.wireframeMesh.rotation.copy(this.mesh.rotation)
    this.wireframeMesh.position.copy(this.mesh.position)
    this.wireframeMesh.renderOrder = 2

    this.instance.add(this.wireframeMesh)
  }

  triggerWave(_params) {
    const params = {
      direction: _params.direction !== undefined ? _params.direction : 1,
      duration: _params.duration !== undefined ? _params.duration : 4.25,
      ease: _params.ease !== undefined ? _params.ease : 'power2.inOut',
      delay: _params.delay !== undefined ? _params.delay : 0,
      intensity: _params.intensity !== undefined ? _params.intensity : 1.0,
      lightIntensity: _params.lightIntensity !== undefined ? _params.lightIntensity : 1.0,
    }

    this.material.uniforms.uLightIntensity.value = params.lightIntensity
    this.material.uniforms.uIntensity.value = params.intensity

    if (params.direction === 1) {
      gsap.fromTo(
        this.material.uniforms.uWaveTransition,
        {
          value: 0.0,
        },
        {
          value: 1,
          delay: params.delay,
          duration: params.duration,
          ease: params.ease,
          onStart: () => {
            this.isAnimating = true
          },
          onUpdate: () => {
            this.material.uniforms.uTime.value += Math.sin(this.material.uniforms.uWaveTransition.value * Math.PI) * this.gl.time.delta * 0.075
          },
          onComplete: () => {
            this.isAnimating = false
          },
        }
      )
    } else {
      gsap.fromTo(
        this.material.uniforms.uWaveTransition,
        {
          value: 1,
        },
        {
          value: 0,
          duration: 2.75,
          ease: 'expo.inOut',
          onStart: () => {
            this.isAnimating = true
          },
          onUpdate: () => {
            // this.material.uniforms.uTime.value -= Math.sin(this.material.uniforms.uWaveTransition.value * Math.PI) * 0.05
          },
          onComplete: () => {
            this.isAnimating = false
          },
        }
      )
    }
  }

  update() {
    const normalizedFrequency = this.gl.audio.frequencies.synthLoop.current * 0.005

    // console.log(this.gl.time.delta)

    this.material.uniforms.uTime.value += (0.25 + this.globalSpeed * 0.75) * this.gl.time.delta * 0.01
    this.material.uniforms.uTime.value += normalizedFrequency * this.gl.time.delta * 0.5

    this.material.uniforms.uFrequency.value = normalizedFrequency

    // console.log(this.gl.audio.analysers.synthLoop)
  }
}

import * as THREE from 'three'
import { GPUComputationRenderer } from 'three/addons/misc/GPUComputationRenderer.js'
import gsap from '@/gsap'

import Gl from '@/gl/Gl'
import { Scroll } from '@/scroll'

export default class Particles {
  constructor() {
    this.gl = new Gl()

    this.instance = new THREE.Group()

    /* 
      Settings
    */
    this.settings = {
      scale: 0.25,
    }

    /* 
      Global
    */
    this.globalSpeed = 1.0

    /* 
      Base Geometry
    */
    this.baseGeometry = {}
    this.baseGeometry.instance = new THREE.TorusGeometry(5, this.settings.scale, 48, 48)
    this.baseGeometry.count = this.baseGeometry.instance.attributes.position.count

    /* 
      GPU Compute
    */
    this.gpgpu = {}
    this.gpgpu.size = Math.ceil(Math.sqrt(this.baseGeometry.count))

    this.gpgpu.computation = new GPUComputationRenderer(this.gpgpu.size, this.gpgpu.size, this.gl.renderer.instance)

    this.baseParticlesTexture = this.gpgpu.computation.createTexture()

    for (let i = 0; i < this.baseGeometry.count; i++) {
      this.baseParticlesTexture.image.data[i * 4 + 0] = this.baseGeometry.instance.attributes.position.array[i * 3 + 0] + (2 * Math.random() - 1) * this.settings.scale
      this.baseParticlesTexture.image.data[i * 4 + 1] = this.baseGeometry.instance.attributes.position.array[i * 3 + 1] + (2 * Math.random() - 1) * this.settings.scale
      this.baseParticlesTexture.image.data[i * 4 + 2] = this.baseGeometry.instance.attributes.position.array[i * 3 + 2] + (2 * Math.random() - 1) * this.settings.scale
      this.baseParticlesTexture.image.data[i * 4 + 3] = Math.random()
    }

    this.shader = /* glsl */ `
      #include <simplex>

      uniform float uTime;
      uniform float uTransition;
      uniform float uDeltaTime;
      uniform float uFrequency;

      uniform sampler2D uBasePositions;

      const float FLOWFIELD_SIZE = .25;
      const float FLOWFIELD_CHUNK_SIZE = 10.;
      const float FLOWFIELD_STRENGTH = 5.;

      void main() {
        vec2 uv = gl_FragCoord.xy / resolution.xy;
        vec4 particleTexture = texture2D(uParticles, uv);
        vec4 basePositionTexture = texture2D(uBasePositions, uv);

        if (particleTexture.a >= 1.0) {
          // If Dead
          particleTexture.a = fract(particleTexture.a);
          particleTexture.xyz = basePositionTexture.xyz;
        } else {
          // Distribution Strength
          // float distributionStrength = simplexNoise4d(vec4(basePositionTexture.xyz * FLOWFIELD_CHUNK_SIZE, uTime * 0.1 + 1.0));
          // distributionStrength = smoothstep(0.0, 1.0, distributionStrength);

          // If Alive, apply flow field
          vec3 flowField = vec3(
            simplexNoise4d(vec4(particleTexture.xyz * FLOWFIELD_SIZE + 0.0, uTime * 0.25)),
            simplexNoise4d(vec4(particleTexture.xyz * FLOWFIELD_SIZE + 1.0, uTime * 0.25)),
            simplexNoise4d(vec4(particleTexture.xyz * FLOWFIELD_SIZE + 2.0, uTime * 0.25))
          );

          flowField = normalize(flowField);
          particleTexture.xyz += flowField * (FLOWFIELD_STRENGTH + (1.0 - uTransition) * 10.) * uDeltaTime;

          // Decay
          particleTexture.a += uDeltaTime;
        }

        gl_FragColor = mix(particleTexture, basePositionTexture, pow(uFrequency * 15., 3.0));
      }
    `

    this.gpgpu.particlesVariable = this.gpgpu.computation.addVariable('uParticles', this.shader, this.baseParticlesTexture)
    this.gpgpu.computation.setVariableDependencies(this.gpgpu.particlesVariable, [this.gpgpu.particlesVariable])

    // Uniforms
    this.gpgpu.particlesVariable.material.uniforms.uTime = new THREE.Uniform(0.0)
    this.gpgpu.particlesVariable.material.uniforms.uDeltaTime = new THREE.Uniform(0.0)
    this.gpgpu.particlesVariable.material.uniforms.uBasePositions = new THREE.Uniform(this.baseParticlesTexture)
    this.gpgpu.particlesVariable.material.uniforms.uTransition = new THREE.Uniform(0.0)
    this.gpgpu.particlesVariable.material.uniforms.uFrequency = new THREE.Uniform(0.0)
    this.gpgpu.computation.init()

    /* 
      Particles
    */
    this.particles = {}

    this.particlesUvArray = new Float32Array(this.baseGeometry.count * 2)
    this.randomArray = new Float32Array(this.baseGeometry.count)

    for (let y = 0; y < this.gpgpu.size; y++) {
      for (let x = 0; x < this.gpgpu.size; x++) {
        const i = y * this.gpgpu.size + x
        const i2 = i * 2

        const uvX = (x + 0.5) / this.gpgpu.size
        const uvY = (y + 0.5) / this.gpgpu.size

        this.particlesUvArray[i2 + 0] = uvX
        this.particlesUvArray[i2 + 1] = uvY

        this.randomArray[i] = Math.random()
      }
    }

    this.particles.geometry = new THREE.BufferGeometry()
    this.particles.geometry.setDrawRange(0, this.baseGeometry.count)
    this.particles.geometry.setAttribute('aParticlesUv', new THREE.BufferAttribute(this.particlesUvArray, 2))
    this.particles.geometry.setAttribute('aRandom', new THREE.BufferAttribute(this.randomArray, 1))
    this.particles.geometry.boundingSphere = new THREE.Sphere(
      new THREE.Vector3(0, 0, 0), // Center
      10 // Radius (big enough to contain all particles)
    )

    this.particles.material = new THREE.ShaderMaterial({
      transparent: true,
      // blending: THREE.AdditiveBlending,
      uniforms: {
        uSize: new THREE.Uniform(0.115), // 0.15 With size-attenuation
        uResolution: new THREE.Uniform(new THREE.Vector2(this.gl.sizes.width * this.gl.sizes.pixelRatio, this.gl.sizes.height * this.gl.sizes.pixelRatio)),
        uParticlesTexture: new THREE.Uniform(null),
        uProgress: new THREE.Uniform(1),
        uTransition: new THREE.Uniform(0.0),
        uCircleSize: new THREE.Uniform(0.025),
        uBokeh: new THREE.Uniform(0.0),
        uFocusDistance: new THREE.Uniform(7.5),
        uFocusRange: new THREE.Uniform(0.25),
        uCloseUpBokeh: new THREE.Uniform(0.0),

        COLOR_HIGHLIGHT: new THREE.Uniform(new THREE.Color(0xb2e0ff)),
      },
      vertexShader: /* glsl */ `
        uniform vec2 uResolution;
        uniform float uSize;
        uniform sampler2D uParticlesTexture;
        uniform float uProgress;
        uniform float uTransition;
        uniform float uFocusDistance;
        uniform float uFocusRange;
        uniform float uCloseUpBokeh;
        attribute vec2 aParticlesUv;
        attribute float aRandom;

        varying vec4 vColor;
        varying vec2 vParticlesUv;
        varying float vLifeSize;
        varying float vDepth;

        void main() {
          vec4 particle = texture2D(uParticlesTexture, aParticlesUv);
          particle.z += 15.0 * smoothstep(0.9, 1.0, aRandom) * smoothstep(0.0, 0.3, uProgress);
          // particle.y += particle.z * 0.2;
          // particle.x += particle.z * 0.2;

          // Final position
          vec4 modelPosition = modelMatrix * vec4(particle.xyz, 1.0);
          vec4 viewPosition = viewMatrix * modelPosition;
          vec4 projectedPosition = projectionMatrix * viewPosition;
          gl_Position = projectedPosition;

          // Life Size
          float lifeIn = smoothstep(0.0, 0.1, particle.a);
          float lifeOut = 1.0 - smoothstep(0.9, 1.0, particle.a);
          float lifeSize = min(lifeIn, lifeOut) * smoothstep(0.2, 1.0, uTransition);

          // Point size
          gl_PointSize = aRandom * lifeSize * uSize * uResolution.y;
          // gl_PointSize *= (1.0 / - viewPosition.z);

          // Varyings
          vColor = vec4(vec3(1.0), particle.a);
          vParticlesUv = aParticlesUv;
          vLifeSize = lifeSize;
          vDepth = pow(min(abs((uFocusDistance + viewPosition.z - uCloseUpBokeh * 5.0) * uFocusRange), 1.0), 2.0);
        }
      `,
      fragmentShader: /* glsl */ `
        varying vec4 vColor;
        varying vec2 vParticlesUv;
        varying float vLifeSize;
        varying float vDepth;

        uniform sampler2D uParticlesTexture;
        uniform float uCircleSize;
        uniform float uBokeh;
        uniform float uCloseUpBokeh;

        uniform float uTransition;
        uniform vec3 COLOR_HIGHLIGHT;

        void main() {
          vec4 particle = texture2D(uParticlesTexture, vParticlesUv);

          float distanceToCenter = length(gl_PointCoord - 0.5);
          if(distanceToCenter > 0.5) discard;

          float mask = 1.0 - distance(distanceToCenter, 0.25 / 8.0) * 8.0;
          mask = smoothstep(1.0 - uCircleSize - pow(uBokeh, 2.0) * 8.0 * vDepth, 1.0, mask);

          vec4 color = vec4(COLOR_HIGHLIGHT, max(mask, 0.25 * step(distanceToCenter, 0.25 / 8.0)) * vLifeSize);
          color.a -= (pow(uBokeh, 0.5) * (0.75 + vDepth * 0.25));
          color.a = max(color.a, 0.0);

          gl_FragColor = color;
        }
      `,
    })

    this.particles.material.depthWrite = false

    this.mesh = new THREE.Points(this.particles.geometry, this.particles.material)

    this.mesh.rotation.x = -Math.PI * 0.425
    this.mesh.position.set(0.114, 1.82, -0.48)
    this.mesh.renderOrder = 2

    this.instance.add(this.mesh)

    /* 
      Functions
    */
    // this.setProgress()
  }

  // setProgress(_progress) {
  //   // Default
  //   this.particles.material.uniforms.uProgress.value = 1
  // }

  triggerHover() {
    const tl = gsap.timeline({
      delay: 0.5,
    })

    tl.fromTo(
      this.mesh.scale,
      {
        x: 1,
        y: 1,
        z: 1,
      },
      {
        x: 1.15,
        y: 1.15,
        z: 1.15,
        duration: 0.5,
        ease: 'power2.inOut',
      }
    )

    tl.fromTo(
      this.mesh.scale,
      {
        x: 1.15,
        y: 1.15,
        z: 1.15,
      },
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 2,
        ease: 'power2.inOut',
        immediateRender: false,
      }
    )
  }

  triggerWave(_direction, _duration, _ease, _animateStrength = false, _delay) {
    if (_direction === 1) {
      gsap.fromTo(
        this.mesh.scale,
        {
          x: 0.1,
          y: 0.1,
          z: 0.1,
        },
        {
          x: 1,
          y: 1,
          z: 1,
          delay: _delay ? _delay : 0,
          duration: _duration != undefined ? _duration : 4.1,
          ease: _ease ? _ease : 'power2.inOut',
        }
      )

      gsap.fromTo(
        this.particles.material.uniforms.uTransition,
        {
          value: 0.0,
        },
        {
          value: 1.0,
          duration: _duration != undefined ? _duration : 4.1,
          ease: _ease ? _ease : 'power2.inOut',
        }
      )

      if (_animateStrength) {
        gsap.fromTo(
          this.gpgpu.particlesVariable.material.uniforms.uTransition,
          {
            value: 0.0,
          },
          {
            value: 1.0,
            duration: _duration != undefined ? _duration : 4.1,
            ease: _ease ? _ease : 'power2.inOut',
          }
        )
      }
    } else {
      gsap.fromTo(
        this.mesh.scale,
        {
          x: 1,
          y: 1,
          z: 1,
        },
        {
          x: 0.1,
          y: 0.1,
          z: 0.1,
          duration: _duration != undefined ? _duration : 2.75,
          ease: 'expo.inOut',
        }
      )

      gsap.fromTo(
        this.particles.material.uniforms.uTransition,
        {
          value: 1.0,
        },
        {
          value: 0,
          duration: _duration != undefined ? _duration : 2.75,
          ease: 'expo.inOut',
        }
      )

      if (_animateStrength) {
        gsap.fromTo(
          this.gpgpu.particlesVariable.material.uniforms.uTransition,
          {
            value: 1.0,
          },
          {
            value: 0.0,
            duration: _duration != undefined ? _duration : 2.75,
            ease: 'expo.inOut',
          }
        )
      }
    }
  }

  resize() {
    this.particles.material.uniforms.uResolution.value = new THREE.Vector2(this.gl.sizes.width * this.gl.sizes.pixelRatio, this.gl.sizes.height * this.gl.sizes.pixelRatio)
  }

  update() {
    this.gpgpu.particlesVariable.material.uniforms.uTime.value += (this.gl.time.delta * 0.0125 - this.gl.audio.frequencies.synthLoop.current * this.gl.time.delta * 0.0005) * (0.25 + this.globalSpeed * 0.75)
    this.gpgpu.particlesVariable.material.uniforms.uDeltaTime.value = this.gl.time.delta * 0.001 * (0.25 + this.globalSpeed * 0.75)
    this.gpgpu.computation.compute()
    this.particles.material.uniforms.uParticlesTexture.value = this.gpgpu.computation.getCurrentRenderTarget(this.gpgpu.particlesVariable).texture

    /* 
      Rotation
    */
    this.mesh.rotation.z += this.gl.time.delta * 0.00075 * this.globalSpeed

    /* 
      Frequency
    */
    this.gpgpu.particlesVariable.material.uniforms.uFrequency.value = this.gl.audio.frequencies.synthLoop.current * 0.001
  }
}

