    this.fwa.rotation.set(Math.PI / 2.5, 0, 0)
    this.parent.add(this.fwa)
  }

  setRotationAnimation() {
    /* 
      Start
    */
    this.rotationTimeline = gsap.timeline({
      paused: true,
    })

    this.rotationTimeline.fromTo(
      this.parent.rotation,
      {
        y: -Math.PI / 8,
        z: -Math.PI / 12,
      },
      {
        y: Math.PI * 3.3 + Math.PI / 2,
        z: -Math.PI / 5,
        ease: 'none',
        duration: 1,
      }
    )
  }

  setEmissiveAnimation() {
