      if (this.activeScenes.current.hoveredEarphoneDOM == 'earphone-r-raycast-volume-up') {
        gsap.to(this.activeScenes.current.materialEarphoneBaseR.uniforms.uVolumeShadowUp, {
          value: 0.25,
          duration: 0.1,
          ease: 'none',
        })

        gsap.to(this.activeScenes.current.earphoneRVolume.rotation, {
          z: this.activeScenes.current.modelsInitialParams.earphoneVolume.rotation.z + 0.035,
          duration: 0.1,
          ease: 'none',
          onComplete: () => {
            this.activeScenes.current.triggerVolumeHover(1, 'up')
          },
        })

        gsap.to(this.activeScenes.current.earphoneRVolume.position, {
          x: this.activeScenes.current.modelsInitialParams.earphoneVolume.position.x - 0.01,
          duration: 0.1,
          ease: 'none',
        })

        this.gl.audio.setGlobalVolume(1)
      } else if (this.activeScenes.current.hoveredEarphoneDOM == 'earphone-r-raycast-volume-down') {
        gsap.to(this.activeScenes.current.materialEarphoneBaseR.uniforms.uVolumeShadowDown, {
          value: 0.25,
          duration: 0.1,
          ease: 'none',
        })

        gsap.to(this.activeScenes.current.earphoneRVolume.rotation, {
          z: this.activeScenes.current.modelsInitialParams.earphoneVolume.rotation.z - 0.035,
          duration: 0.1,
          ease: 'none',
          onComplete: () => {
            this.activeScenes.current.triggerVolumeHover(1, 'down')
          },
        })

        gsap.to(this.activeScenes.current.earphoneRVolume.position, {
          x: this.activeScenes.current.modelsInitialParams.earphoneVolume.position.x - 0.01,
          duration: 0.1,
          ease: 'none',
        })

        this.gl.audio.setGlobalVolume(-1)
      }
    })
  }

  destroy() {
    if (this.gl.isDebug) console.log('Before destroy:', this.gl.renderer.instance.info)

    /* 
      Scenes
    */
    for (const key in this.scenes) {
      // Remove everything from the scene and dispose
      this.gl.scene.remove(this.scenes[key].renderPlane.mesh)
      if (this.scenes[key].renderTarget) this.scenes[key].renderTarget.dispose()
      this.scenes[key].renderPlane.mesh.geometry.dispose()
      this.scenes[key].renderPlane.mesh.material.dispose()

      // Remove everything from the scene
      if (this.scenes[key].scene) {
        this.scenes[key].scene.traverse((object) => {
          this.scenes[key].scene.remove(object.name)

          if (!object.isMesh) return

          object.geometry.dispose()

          if (object.material.isMaterial) {
            this.cleanMaterial(object.material)
          } else {
            // an array of materials
            for (const material of object.material) this.cleanMaterial(material)
          }
        })
      }
    }

    this.selectors = []
    this.scenes = []

    // Clear renderer image
    this.gl.renderer.instance.setRenderTarget(null)
    this.gl.renderer.instance.clear()

    if (this.gl.isDebug) console.log('After destroy:', this.gl.renderer.instance.info)
  }

  cleanMaterial(material) {
    material.dispose()

    // dispose textures
    for (const key of Object.keys(material)) {
      const value = material[key]
      if (value && typeof value === 'object' && 'minFilter' in value) {
        value.dispose()
      }
    }
  }

  resize() {
    for (const key in this.scenes) {
      this.scenes[key].resize()
    }

    /* 
      Fluid Cursor
    */
    this.fluidCursor.resize()

    /* 
      Uniforms
    */
    this.renderPlane.mesh.material.uniforms.uAspect.value = this.gl.sizes.width / this.gl.sizes.height

    /* 
      Debug
    */
    if (this.gl.isDebug) {
      this.debugPlane.scale.set(this.targetSize, this.targetSize * this.gl.sizes.aspect, 1)
    }
  }

  update() {
    /* 
      Mouse
    */
    this.mouse.eased.camera.update(this.gl.time.delta)
    this.mouse.eased.fresnel.update(this.gl.time.delta)

    /* 
      Fluid Cursor
    */
    this.fluidCursor.update()
    this.renderPlane.mesh.material.uniforms.tFluidCursor.value = this.fluidCursor.sourceTarget.texture

    /* 
      Scenes
    */
    for (const key in this.scenes) {
      this.scenes[key].update()

      // console.log(this.scenes[key].id, this.scenes[key].isRendering)
    }

    /* 
      Uniforms
    */
    this.renderPlane.mesh.material.uniforms.tCurrent.value = this.activeScenes.current.renderTarget.texture
    this.renderPlane.mesh.material.uniforms.tPrev.value = this.activeScenes.previous.renderTarget.texture

    /* 
      Debug
    */
    if (this.gl.isDebug) {
      if (this.activeScenes.current.id == 'main-a' || this.activeScenes.current.id == 'main-b' || this.activeScenes.current.id == 'easter-egg') {
        this.debugPlane.material.uniforms.tDiffuse.value = this.activeScenes.current.particles.gpgpu.computation.getCurrentRenderTarget(this.activeScenes.current.particles.gpgpu.particlesVariable).texture
      }
    }

    // console.log(Scroll.progress, Scroll.isStopped)

    // console.log(this.renderPlane.mesh.material.uniforms.uTransition.value)
  }
}

import * as THREE from 'three'
import { gsap } from 'gsap'
import Gl from '../Gl'

export default class Audio {
  constructor() {
    this.gl = new Gl()

    /* 
      Flags
    */
    this.isAllowed = false
    this.audioAnimatedIn = false

    /* 
      Default Volumes
    */
    this.defaultVolumes = {
      synthLoop: 1,
      powerLoop: 0.46,
      uiAskAetherOpen: 1,
      uiMenuClose: 0.55,
      uiMenuOpen: 0.55,
      uiQuestionSend: 1,
      uiReply: 0.8,
    }

    /* 
      Global Volume
    */
    this.globalVolume = {
      max: 0.2,
      current: 0.2,
      target: 0.2,
    }

    /* 
     Frequencies
    */
    this.frequencies = {
      synthLoop: {
        current: 0,
        target: 0,
      },
    }

    /* 
      Analysers
    */
    this.analysers = {}

    // this.audio = new Audio();
    /* 
      Functions
    */
    // this.handleFirstInteraction()
  }

  init() {
    // this.animateAudioIn()
    this.addAnalysers()

    /* 
      Set Debug
    */
    if (this.gl.isDebug) this.setDebug()
  }

  animateAudioOut() {
    this.gl.assets.audio.synthLoop.stop()
    this.gl.assets.audio.powerLoop.stop()
  }

  animateAudioIn() {
    // if (isAllowed) {
    // if (this.isAllowed) {
    /* 
      Set Flags
    */
    // this.audioAnimatedIn = true

    /* 
      Reveal background audio
    */
    if (!this.gl.assets.audio.synthLoop.isPlaying) {
      this.gl.assets.audio.synthLoop.play()
      this.gl.assets.audio.synthLoop.setLoop(true)
    }

    if (!this.gl.assets.audio.powerLoop.isPlaying) {
      this.gl.assets.audio.powerLoop.play()
      this.gl.assets.audio.powerLoop.setLoop(true)
    }
    this.gl.assets.audio.powerLoop.setVolume(0)

    this.animateAudio(
      { volume: 0 },
      { volume: 0 },
      {
        //
        volume: 1,
        duration: 1,
        ease: 'power2.inOut',
      },
      (_value) => {
        this.gl.assets.audio.synthLoop.setVolume(_value.volume * this.defaultVolumes.synthLoop)
        // this.gl.assets.audio.powerLoop.setVolume(_value.volume)
      }
    )
    // }
  }

  handleFirstInteraction() {
    document.addEventListener('click', (e) => {
      if (this.isAllowed || !this.gl.isLoaded) return

      /* 
        Set Flags
      */
      this.isAllowed = true

      /* 
        Animate In Audio
      */
      if (!this.audioAnimatedIn && this.gl.isLoaded) this.animateAudioIn()
    })
  }

  addAnalysers() {
    for (const key in this.gl.assets.audio) {
      this.analysers[key] = new THREE.AudioAnalyser(this.gl.assets.audio[key], 32)
    }
  }

  animateAudio(_value, _from, _to, _update) {
    return new Promise((_resolve) => {
      const value = _value

      gsap.fromTo(value, _from, {
        ..._to,
        onUpdate: () => {
          _update(value)
        },
        onComplete: () => {
          _resolve()
        },
      })
    })
  }

  setGlobalVolume(_direction) {
    this.globalVolume.target += _direction * 0.025
    this.globalVolume.target = Math.max(0, Math.min(this.globalVolume.max, this.globalVolume.target))
    // this.globalVolume.target = Math.min(1, this.globalVolume.target)

    // console.log(this.globalVolume.target)

    gsap.to(this.globalVolume, {
      current: this.globalVolume.target,
      duration: 0.2,
      ease: 'none',
      onUpdate: () => {
        for (const key in this.gl.assets.audio) {
          this.gl.assets.audio[key].listener.setMasterVolume(this.globalVolume.current)
        }
      },
    })
  }

  toggleGlobalVolume(_target) {
    // this.globalVolume.target = _target

    gsap.to(this.globalVolume, {
      current: _target,
      duration: 0.4,
      ease: 'none',
      onUpdate: () => {
        for (const key in this.gl.assets.audio) {
          this.gl.assets.audio[key].listener.setMasterVolume(this.globalVolume.current)
        }
      },
    })
  }

  playUI(_sound, _volume) {
    this.gl.assets.audio[_sound].stop()
    this.gl.assets.audio[_sound].play()

    if (_volume != undefined) {
      this.gl.assets.audio[_sound].setVolume(_volume)
    } else {
      this.gl.assets.audio[_sound].setVolume(this.defaultVolumes[_sound])
    }
  }

  setDebug() {
    const audioFolder = this.gl.debug.gui.addFolder('Audio').close()

    audioFolder
      .add({ value: 1 }, 'value')
      .name('Global volume')
      .min(0)
      .max(1)
      .step(0.01)
      .onChange((_value) => {
        for (const key in this.gl.assets.audio) {
          this.gl.assets.audio[key].listener.setMasterVolume(_value)
        }
      })

    const individualVolumeFolder = audioFolder.addFolder('Individual Volumes')

    for (const key in this.defaultVolumes) {
      individualVolumeFolder
        .add({ value: this.defaultVolumes[key] }, 'value')
        .name(key)
        .min(0)
        .max(2)
        .step(0.01)
        .onChange((_value) => {
          this.defaultVolumes[key] = _value

          if (key == 'synthLoop') {
            this.gl.assets.audio.synthLoop.setVolume(_value)
          }
        })
    }
  }

  update() {
    /* 
      Frequencies
    */
    this.frequencies.synthLoop.current = THREE.MathUtils.damp(this.frequencies.synthLoop.current, this.analysers.synthLoop.getFrequencyData()[5], 0.0025, this.gl.time.delta)

    // console.log(this.analysers.synthLoop.getFrequencyData())
  }
}

export default class EventEmitter
{
    constructor()
    {
        this.callbacks = {}
        this.callbacks.base = {}
    }

    on(_names, callback)
    {
        // Errors
        if(typeof _names === 'undefined' || _names === '')
        {
            console.warn('wrong names')
            return false
        }

        if(typeof callback === 'undefined')
        {
            console.warn('wrong callback')
            return false
        }

        // Resolve names
        const names = this.resolveNames(_names)

        // Each name
        names.forEach((_name) =>
        {
            // Resolve name
            const name = this.resolveName(_name)

            // Create namespace if not exist
            if(!(this.callbacks[ name.namespace ] instanceof Object))
                this.callbacks[ name.namespace ] = {}

            // Create callback if not exist
            if(!(this.callbacks[ name.namespace ][ name.value ] instanceof Array))
                this.callbacks[ name.namespace ][ name.value ] = []

            // Add callback
            this.callbacks[ name.namespace ][ name.value ].push(callback)
        })

        return this
    }

    off(_names)
    {
        // Errors
        if(typeof _names === 'undefined' || _names === '')
        {
            console.warn('wrong name')
            return false
        }

        // Resolve names
        const names = this.resolveNames(_names)

        // Each name
        names.forEach((_name) =>
        {
            // Resolve name
            const name = this.resolveName(_name)

            // Remove namespace
            if(name.namespace !== 'base' && name.value === '')
            {
                delete this.callbacks[ name.namespace ]
            }

            // Remove specific callback in namespace
            else
            {
                // Default
                if(name.namespace === 'base')
                {
                    // Try to remove from each namespace
                    for(const namespace in this.callbacks)
                    {
                        if(this.callbacks[ namespace ] instanceof Object && this.callbacks[ namespace ][ name.value ] instanceof Array)
                        {
                            delete this.callbacks[ namespace ][ name.value ]

                            // Remove namespace if empty
                            if(Object.keys(this.callbacks[ namespace ]).length === 0)
                                delete this.callbacks[ namespace ]
                        }
                    }
                }

                // Specified namespace
                else if(this.callbacks[ name.namespace ] instanceof Object && this.callbacks[ name.namespace ][ name.value ] instanceof Array)
                {
                    delete this.callbacks[ name.namespace ][ name.value ]

                    // Remove namespace if empty
                    if(Object.keys(this.callbacks[ name.namespace ]).length === 0)
                        delete this.callbacks[ name.namespace ]
                }
            }
        })

        return this
    }

    trigger(_name, _args)
    {
        // Errors
        if(typeof _name === 'undefined' || _name === '')
        {
            console.warn('wrong name')
            return false
        }

        let finalResult = null
        let result = null

        // Default args
        const args = !(_args instanceof Array) ? [] : _args

        // Resolve names (should on have one event)
        let name = this.resolveNames(_name)

        // Resolve name
        name = this.resolveName(name[ 0 ])

        // Default namespace
        if(name.namespace === 'base')
        {
            // Try to find callback in each namespace
            for(const namespace in this.callbacks)
            {
                if(this.callbacks[ namespace ] instanceof Object && this.callbacks[ namespace ][ name.value ] instanceof Array)
                {
                    this.callbacks[ namespace ][ name.value ].forEach(function(callback)
                    {
                        result = callback.apply(this, args)

                        if(typeof finalResult === 'undefined')
                        {
                            finalResult = result
                        }
                    })
                }
            }
        }

        // Specified namespace
        else if(this.callbacks[ name.namespace ] instanceof Object)
        {
            if(name.value === '')
            {
                console.warn('wrong name')
                return this
            }

            this.callbacks[ name.namespace ][ name.value ].forEach(function(callback)
            {
                result = callback.apply(this, args)

                if(typeof finalResult === 'undefined')
                    finalResult = result
            })
        }

        return finalResult
    }

    resolveNames(_names)
    {
        let names = _names
        names = names.replace(/[^a-zA-Z0-9 ,/.]/g, '')
        names = names.replace(/[,/]+/g, ' ')
        names = names.split(' ')

        return names
    }

    resolveName(name)
    {
        const newName = {}
        const parts = name.split('.')

        newName.original  = name
        newName.value     = parts[ 0 ]
        newName.namespace = 'base' // Base namespace

        // Specified namespace
        if(parts.length > 1 && parts[ 1 ] !== '')
        {
            newName.namespace = parts[ 1 ]
        }

        return newName
    }
}

import EventEmitter from './EventEmitter.js'
import { Clock } from 'three'

export default class Time extends EventEmitter {
  constructor() {
    super()

    // Setup
    this.clock = new Clock()
    this.elapsed = 0
    this.delta = 0

    window.requestAnimationFrame(() => {
      this.tick()
    })
  }

  tick() {
    this.delta = Math.min(this.clock.getDelta(), 1 / 30) * 100 // Prevent long frame jump when tab change in browser - limited to 30fps
    this.elapsed = this.clock.getElapsedTime()

    this.trigger('tick')

    window.requestAnimationFrame(() => {
      this.tick()
    })
  }
}

export default class Sizes {
  constructor() {
    // Setup
    this.width = window.innerWidth
    this.height = window.innerHeight
    this.pixelRatio = Math.min(window.devicePixelRatio, 1.5)
    this.aspect = this.width / this.height
  }

  resize() {
    this.width = window.innerWidth
    this.height = window.innerHeight
    this.pixelRatio = Math.min(window.devicePixelRatio, 1.5)
    this.aspect = this.width / this.height
  }
}

