import { FontLoader } from 'three/examples/jsm/loaders/FontLoader.js'
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js'

import gsap from '@/gsap'

import Gl from '../Gl'

export default class Assets {
  constructor() {
    this.gl = new Gl()

    /* 
      Path
    */
    this.path = 'https://aether1.itsoffbrand.io/assets'

    /* 
      Loaders
    */
    this.dracoLoader = new DRACOLoader()
    this.dracoLoader.setDecoderPath(this.path + '/draco/')

    this.gltfLoader = new GLTFLoader()
    this.gltfLoader.setDRACOLoader(this.dracoLoader)
    this.rgbeLoader = new RGBELoader()
    this.textureLoader = new THREE.TextureLoader()
    this.fontLoader = new FontLoader()
    this.audioLoader = new THREE.AudioLoader()

    /* 
      Assets
    */
    this.models = {}
    this.textures = {}
    this.hdris = {}
    this.fonts = {}

    /* 
      Progress
    */
    this.promisesProgress = 0
    this.promisesTarget = 0
  }

  customTextureLoader(_path, _target) {
    return new Promise((_resolve) => {
      this.textureLoader.load(
        _path,
        (_result) => {
          _resolve()

          _target(_result)

          this.updateProgressDOM()

          if (this.gl.isDebug) this.logProgress(_path)
        },
        undefined,
        (_error) => {
          console.error(_error)
        }
      )
    })
  }

  customModelLoader(_path, _target) {
    return new Promise((_resolve) => {
      this.gltfLoader.load(
        _path,
        (_result) => {
          _resolve()

          _target(_result)

          this.updateProgressDOM()

          if (this.gl.isDebug) this.logProgress(_path)
        },
        undefined,
