  displayResponse(response) {
    // update textarea height
    this.questionWrapperHeight =
      this.questionWrapper.getBoundingClientRect().height + 6;
    this.responseWrapper.style.marginBottom = this.questionWrapperHeight + "px";

    this.response.textContent = response.short;
    this.responseTitle.textContent = response.title;
    // update media based on CTA
    // CTA_1 – See the Specifications (link)
    // CTA_2 – Contact the Manufacturer (email)
    // CTA_3 – Buy Now (link)
    // CTA_4 – Know More (modal)
    switch (response.CTA) {
      case "CTA_1":
        this.responseVisual.src = `https://aether1.itsoffbrand.io/assets/ai-images/${response.media}.webp`;
        break;
      case "CTA_2":
        this.responseVisual.src =
          "https://aether1.itsoffbrand.io/assets/ai-images/avatar1.webp";
        break;
      case "CTA_3":
        this.responseVisual.src =
          "https://aether1.itsoffbrand.io/assets/ai-images/avatar2.webp";
        break;
      case "CTA_4":
        if (response.media.includes("error")) {
          this.responseVisual.src =
            "https://aether1.itsoffbrand.io/assets/ai-images/avatar1.webp";
        }
        if (response.media.includes("VIDEO")) {
          this.responseVisual.src =
            "https://aether1.itsoffbrand.io/assets/ai-images/avatar1.webp";
        }
        if (response.media.includes("IMAGE")) {
          this.responseVisual.src = `https://aether1.itsoffbrand.io/assets/ai-images/${response.media}.webp`;
        }
        break;
    }

    // Display response once content ready
    this.responseWrapper.style.display = "flex";

    // Transition animations
    this.tlThinking?.pause();
    this.tlThinking?.kill();
    this.tlResponse = this.createResponseTimelineFor(this.STATES.RESPONSE);
    this.tlResponse.restart();

    // Update state classes
    html.classList.add(CLASS.AI_RESPONSE);
    html.classList.remove(CLASS.AI_THINKING);
    html.classList.remove(CLASS.AI_ERROR);

    // Handle CTAs
    if (this.CTAs[response.CTA]) {
      gsap.set(this.CTAs[response.CTA], { display: "flex" });
    } else {
      console.warn(`CTA not found: ${response.CTA}`);
    }

    // Animate response in
    gsap.fromTo(
      this.responseWrapper,
      {
        autoAlpha: 0,
        scale: 1.2,
        filter: "blur(1rem)",
      },
      {
        autoAlpha: 1,
        scale: 1,
        filter: "blur(0rem)",
        duration: 0.3,
      }
    );
  }

  resetPrompt() {
    this.form.classList.remove("is--thinking");
    html.classList.remove(CLASS.AI_THINKING);
    this.buttonInner.disabled = false;
    this.question.disabled = false;
  }

  initEventListeners() {
    this.CTAs.CTA_4.addEventListener("click", async (e) => {
      //open modal
      this.Modal.open();

      // Hide response first
      await gsap.to(this.responseWrapper, {
        autoAlpha: 0,
        scale: 1.2,
        filter: "blur(1rem)",
        duration: 0.3,
      });
      this.responseWrapper.style.display = "none";

      // Reset state
      this.currentState = this.STATES.RESPONSE;
      gsap.set(this.questionWrapper, { clearProps: "all" });
      html.classList.remove(CLASS.AI_RESPONSE);
      this.question.value = "";
      gsap.set(Object.values(this.CTAs), { display: "none" });

      // Get containers and positions
      const modalContainer = document.querySelector(".modal__aether-w"); // need to replace with [data-ai='w']?
      const originalBounds = this.form.getBoundingClientRect();

      await gsap.to(this.form, {
        y: 40,
        opacity: 0,
        duration: 0.3,
        ease: easePrimary,
      });

      const flipState = Flip.getState(this.form, {
        props: "width,height,borderRadius,opacity",
        simple: true,
      });

      modalContainer.appendChild(this.form);

      const finalPosition = this.form.getBoundingClientRect();
      const slideUpDistance = window.innerHeight - finalPosition.top + 40;

      gsap.set(this.form, {
        y: slideUpDistance,
        opacity: 0,
      });

      Flip.from(flipState, {
        duration: 0.3,
        ease: easePrimary,
        scale: true,
        onStart: () => {
          this.transitionToState(this.STATES.MODAL_INITIAL);
          // this.transitionToState(this.STATES.INITIAL);
        },
        onComplete: () => {
          gsap.to(this.form, {
            y: 0,
            opacity: 1,
            duration: 0.3,
            ease: easePrimary,
          });
        },
      });
    });

    this.closeQuestion.addEventListener("click", (e) => {
      e.stopPropagation();

      this.requestDismissed = true;
      this.requestController?.abort();
      this.tlThinking?.kill();
      this.responseWrapper.style.display = "none";
      // close modal
      if (html.classList.contains(CLASS.MODAL_OPEN)) {
        this.Modal.close();
      }

      this.transitionToState(this.STATES.INITIAL);

      // Hide response
      // this.hideResponse();
      // gsap.to(this.responseWrapper, {
      //   autoAlpha: 0,
      //   scale: 1.2,
      //   filter: "blur(1rem)",
      //   transformOrigin: "center center",
      //   // y: 20,
      //   duration: 0.3,
      //   onComplete: () => {
      //     this.responseWrapper.style.display = "none";

      //     // Reset input field
      //     this.question.value = "";

      //     // Hide any visible CTAs
      //     gsap.set(Object.values(this.CTAs), { display: "none" });

      //     this.currentState = this.STATES.RESPONSE;
      //     this.transitionToState(this.STATES.EXPANDED);

      //     // this.buttonInner.style.pointerEvents = "auto";
      //     // this.buttonInner.style.cursor = "";
      //     this.button.disabled = false;
      //     this.question.disabled = false;
      //     html.classList.remove(CLASS.AI_THINKING);

      //     gsap.set(this.questionWrapper, {
      //       clearProps: "all"
      //     });
      //     html.classList.remove(CLASS.AI_RESPONSE)

      //   }
      // });
    });

    this.buttonInner.addEventListener("click", (e) => {
      // e.stopPropagation();
      this.toggleState();
    });

    window.addEventListener("keydown", (e) => {
      // ESC handler
      if (
        e.key === "Escape" &&
        this.currentState === this.STATES.EXPANDED &&
        !this.isAnimating
      ) {
        this.transitionToState(this.STATES.INITIAL);
      }

      // Enter key handler (only in expanded state)
      if (
        e.key === "Enter" &&
        (this.currentState === this.STATES.EXPANDED ||
          this.currentState === this.STATES.MODAL_EXPANDED) &&
        !this.isAnimating
      ) {
        this.handleEnterKey(e);
      }
    });
  }

  handleEnterKey(e) {
    e.preventDefault();

    // 3 character minimum TBC?
    if (this.question.value.length < 4) {
      this.playShakeAnimation();
      return;
    }

    this.submitQuestion();
  }

  hideResponse() {
    gsap.to(this.responseWrapper, {
      autoAlpha: 0,
      scale: 1.2,
      filter: "blur(1rem)",
      transformOrigin: "center center",
      // y: 20,
      duration: 0.3,
      onComplete: () => {
        this.responseWrapper.style.display = "none";

        // Reset input field
        this.question.value = "";

        // Hide any visible CTAs
        gsap.set(Object.values(this.CTAs), { display: "none" });

        this.currentState = this.STATES.RESPONSE;
        // this.transitionToState(this.STATES.EXPANDED);

        this.button.disabled = false;
        this.question.disabled = false;
        html.classList.remove(CLASS.AI_THINKING);

        gsap.set(this.questionWrapper, {
          clearProps: "all",
        });
        html.classList.remove(CLASS.AI_RESPONSE);
      },
    });
  }
  playShakeAnimation() {
    if (this.shakeTween) this.shakeTween.kill();
    this.shakeTween = gsap.to(this.questionWrapper, {
      ...this.shakeConfig,
      onInterrupt: () => gsap.set(this.questionWrapper, { clearProps: "x" }),
      onComplete: () => gsap.set(this.questionWrapper, { clearProps: "x" }),
    });
  }

  outsideClickBind = (e) => {
    if (
      this.currentState === this.STATES.EXPANDED &&
      !this.form.contains(e.target) &&
      !this.isAnimating
    ) {
      this.transitionToState(this.STATES.INITIAL);
    }
  };

  async submitQuestion() {
    if (this.isSubmitting) return;
    this.isSubmitting = true;
    this.requestDismissed = false;
    this.hasStreamPreview = false;
    this.submittedQuestion = this.question.value;
    const controller = new AbortController();
    this.requestController = controller;
    const timeout = setTimeout(() => controller.abort(), 60_000);

    try {
      if (this.currentState === this.STATES.EXPANDED) {
        await this.transitionToState(this.STATES.THINKING);
      } else if (this.currentState === this.STATES.MODAL_EXPANDED) {
        // Close any open accordion
        if (this.accordions.length > 0) {
          this.accordions.forEach((accordion) => {
            if (accordion.$details.open) {
              accordion.shrink();
            }
          });
        }
        await this.transitionToState(this.STATES.MODAL_THINKING);
      }

      const response = await fetch(url(), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/x-ndjson",
        },
        body: JSON.stringify({ question: this.submittedQuestion }),
        signal: controller.signal,
      });

      const text = await readAnswer(response, (raw) => {
        if (!controller.signal.aborted) this.displayStreamingResponse(raw);
      });
      if (!controller.signal.aborted) {
        await this.handleResponse({ result: { content: [{ text: { value: text } }] } });
      }
    } catch (error) {
      // Transition to error state
      if (!this.destroyed && !this.requestDismissed) this.transitionToErrorState();
      console.error("Submission failed:", error);
    } finally {
      clearTimeout(timeout);
      this.isSubmitting = false;
      this.requestController = null;
      this.requestDismissed = false;
    }
  }

  transitionToThinkingState() {
    html.classList.add(CLASS.AI_THINKING);
    this.buttonInner.disabled = true;
    this.question.disabled = true;
  }

  handleSubmitClick(e) {
    e.stopPropagation();
    this.toggleState();
  }

  destroy() {
    this.destroyed = true;
    this.requestController?.abort();
    // console.log('Destroying Aether...');

    this.tlExpand?.kill();
    this.tlCollapse?.kill();
    this.tlThinking?.kill();
    this.tlResponse?.kill();

    this.buttonInner?.removeEventListener("click", this.toggleState);
    window.removeEventListener("keydown", this.handleEnterKey);
    document.removeEventListener("click", this.outsideClickBind);
    this.closeQuestion?.removeEventListener("click", this.hideResponse);

    this.accordions?.forEach((acc) => acc?.destroy?.());
    this.accordions = [];

    html.classList.remove(
      "has-ai-open",
      "has-ai-thinking",
      "has-ai-response",
      "has-ai-error",
      "has-modal-open"
    );

    this.Modal?.destroy?.();
    Aether.instance = null;
  }
}

import { Observe } from './_/observe'
import gsap from '@/gsap'
import { roundNumber } from '../utils/math'
import Gl from '@/gl/Gl'

export class AudioToggler extends Observe {
  static WAVE = {
    POINTS: 25,
    AMPLITUDE_ON: 2.5,
    AMPLITUDE_OFF: 0,
    LENGTH: 2,
    SPEED_ON: 0.1,
    SPEED_OFF: 0,
    OFFSET: 8,
  }

  static instance = null;

  constructor(element) {
    if (AudioToggler.instance) return AudioToggler.instance;
    super(element);
    AudioToggler.instance = this;

    this.el = element;
    this.$path = this.el.querySelector('path');
    this.isAllowed = false;

    this.onToggleAudio = this.onToggleAudio.bind(this);
    this.onUpdate = this.onUpdate.bind(this);
    this.onFirstInteraction = this.onFirstInteraction.bind(this);

    document.addEventListener("firstInteraction", this.onFirstInteraction);

    this.label = {
      unmute: this.el.dataset.label?.split(',')[0] || 'Play audio',
      mute: this.el.dataset.label?.split(',')[1] || 'Mute audio',
    };

    this.gl = new Gl();
    this.init();
  }

  init() {
    if (!this.isRafPlaying) {
      this.initButtonWave();
      this.playRaf();
      this.onToggleAudio();
    }
    this.bindEvents();
    this.enableToggler();

    this.wasAudioOnBeforeFocusLost = false;
    this.onVisibilityChange = this.handleVisibilityChange.bind(this);
    document.addEventListener('visibilitychange', this.onVisibilityChange);
  }

  bindEvents() {
    this.el.addEventListener('click', this.onToggleAudio);
  }

  unbindEvents() {
    this.el.removeEventListener('click', this.onToggleAudio);
  }

  onFirstInteraction() {
    if (this.isAllowed) return;

    this.isAllowed = true;
    this.onToggleAudio();
  }

  handleVisibilityChange() {
    if (document.hidden) {
      if (this.wave.targetAmplitude > 0) {
        this.wasAudioOnBeforeFocusLost = true;
        this.onToggleAudio(); // Turn audio off
      } else {
        this.wasAudioOnBeforeFocusLost = false;
      }
    } else {
      if (this.wasAudioOnBeforeFocusLost && this.wave.targetAmplitude === 0) {
        this.onToggleAudio(); // Turn audio back on
      }
    }
  }

  onToggleAudio() {
    this.isTurningOff = this.wave.targetAmplitude > 0

    if (this.isTurningOff) {
      this.el.classList.remove('is-active');
      this.wave.targetAmplitude = AudioToggler.WAVE.AMPLITUDE_OFF;
      this.wave.targetSpeed = AudioToggler.WAVE.SPEED_OFF;
      this.el.setAttribute('aria-label', this.label.mute);
      // this.gl.audio.animateAudioOut();
      this.gl.audio.toggleGlobalVolume(0);
    } else {
      this.el.classList.add('is-active');
      this.wave.targetAmplitude = AudioToggler.WAVE.AMPLITUDE_ON;
      this.wave.targetSpeed = AudioToggler.WAVE.SPEED_ON;
      this.el.setAttribute('aria-label', this.label.unmute);
      this.playRaf();
      this.gl.audio.animateAudioIn();
      this.gl.audio.toggleGlobalVolume(0.2);
    }
  }

  initButtonWave() {
    this.wave = {
      amplitude: AudioToggler.WAVE.AMPLITUDE_OFF,
      targetAmplitude: AudioToggler.WAVE.AMPLITUDE_OFF,
      speed: AudioToggler.WAVE.SPEED_OFF,
      targetSpeed: AudioToggler.WAVE.SPEED_OFF,
      points: [],
      time: 0,
    }

    this.isRafPlaying = false
    this.rafIncrement = 0

    for (let i = 0; i <= AudioToggler.WAVE.POINTS; i++) {
      this.wave.points.push(i)
    }

    this.playRaf()
  }

  onUpdate() {
    this.wave.amplitude += (this.wave.targetAmplitude - this.wave.amplitude) * 0.05
    this.wave.speed += (this.wave.targetSpeed - this.wave.speed) * 0.05

    const points = this.wave.points.map((x) => {
      const y = AudioToggler.WAVE.OFFSET + this.wave.amplitude * Math.sin((x + this.wave.time) / AudioToggler.WAVE.LENGTH)
      return [x, y]
    })

    const path = `M${points.map(([x, y]) => `${x},${y}`).join(' L')}`;
    if (this.$path) this.$path.setAttribute('d', path);

    this.wave.time += this.wave.speed

    if (
      roundNumber(this.wave.speed, 3) < 0.01 &&
      roundNumber(this.wave.amplitude, 3) < 0.01
    ) {
      this.rafIncrement++;

      if (this.rafIncrement >= 30) this.pauseRaf();
    }

  }

  resumeWave() {
    if (this.isTurningOff) return;

    this.el = document.querySelector('.sound-w'); // rebind root
    this.el.classList.add('is-active');
    this.$path = this.el?.querySelector('path');     // rebind path

    if (!this.el || !this.$path) {
      console.warn('[AudioToggler] Element or path missing on resume');
      return;
    }

    // Rebind click handler if DOM changed
    this.unbindEvents(); // just in case old one lingers
    this.bindEvents();

    this.wave.targetAmplitude = AudioToggler.WAVE.AMPLITUDE_ON;
    this.wave.targetSpeed = AudioToggler.WAVE.SPEED_ON;
    this.wave.amplitude = 1;
    this.wave.speed = 0.05;
    this.rafIncrement = 0;
    this.playRaf();
  }




  playRaf() {
    if (this.isRafPlaying) return;
    this.isRafPlaying = true;
    this.rafIncrement = 0;
    gsap.ticker.add(this.onUpdate);
  }

  pauseRaf() {
    if (!this.isRafPlaying) return;

    this.isRafPlaying = false;
    gsap.ticker.remove(this.onUpdate);
  }

  enableToggler() {
    this.el.disabled = false;
  }

  disableToggler() {
    this.el.disabled = true;
  }

  destroy() {
    document.removeEventListener("firstInteraction", this.onFirstInteraction);
    document.removeEventListener('visibilitychange', this.onVisibilityChange);
    this.unbindEvents();
    AudioToggler.instance = null;
    super.destroy();
  }
}

export function transform(el, transformValue) {
    el.style.webkitTransform = transformValue;
    el.style.msTransform = transformValue;
    el.style.transform = transformValue;
}

export function getTranslate(el) {
    const translate = {}
    if (!window.getComputedStyle) return;

    const style = getComputedStyle(el);
    const transform = style.transform || style.webkitTransform || style.mozTransform;

    let mat = transform.match(/^matrix3d\((.+)\)$/);
    if (mat) return parseFloat(mat[1].split(', ')[13]);
    mat = transform.match(/^matrix\((.+)\)$/);
    translate.x = mat ? parseFloat(mat[1].split(', ')[4]) : 0;
    translate.y = mat ? parseFloat(mat[1].split(', ')[5]) : 0;

    return translate;
}

import { Observe } from "./_/observe";
import gsap from "@/gsap";
import { lerp } from '../utils/math';
import { transform } from '../utils/transform';
import { isMobile } from "@/utils/media";
import { AudioToggler } from "./AudioToggler";

export class Cursor extends Observe {
    constructor(element) {
        super(element);

        this.el = element;
        this.cursorLabel = this.el.querySelector('.cursor__label');
        this.isClicked = false;

        this.onFirstInteraction = this.onFirstInteraction.bind(this);

        this.init();
    }

    init() {
        if (isMobile()) return;

        document.addEventListener('click', this.onFirstInteraction);

        this.hasMoved = false;
        this.mouse = { x: 0, y: 0, lerpedX: 0, lerpedY: 0 };
        this.animate();

        this.bindMousemove = this.mousemove.bind(this);
        window.addEventListener('mousemove', this.bindMousemove);

        this.bindEnter = this.hover.bind(this);
        this.bindLeave = this.leave.bind(this);

        this.hoverElements = document.querySelectorAll('a, .loader-w');
        this.hoverElements.forEach(el => {
            el.addEventListener('mouseenter', this.bindEnter);
            el.addEventListener('mouseleave', this.bindLeave);
        });

        this.tlCursorIn = gsap.timeline({ paused: true, defaults: { ease: 'none', duration: 0.8 } })
            .fromTo(this.cursorLabel, { opacity: 0 }, { opacity: 1 })
            .fromTo(this.cursorLabel, { text: '' }, {
                text: {
                    value: "[   Click to enable sound   ]",
                    preserveSpaces: true,
                    padSpaces: true,
                    speed: 2
                }
            }, ">");

        this.tlCursorOut = gsap.timeline({
            paused: true,
            defaults: { ease: 'none', duration: 0.6 },
            onComplete: () => {
                this.destroy();
                this.el.remove();
            }
        }).to(this.el, { opacity: 0, filter: 'blur(1rem)' }, ">");
    }

    onFirstInteraction() {
        if (this.isClicked) return;
        this.isClicked = true;

        const audioToggleEl = document.querySelector('.sound-w');
        if (audioToggleEl) {
            new AudioToggler(audioToggleEl); // instantiate here
        } else {
            console.warn('[AudioToggler] No .sound__btn found');
        }

        this.tlCursorOut.play();

        document.removeEventListener('click', this.onFirstInteraction);
    }

    mousemove(e) {
        if (!this.hasMoved) {
            this.hasMoved = true;
            this.el.classList.add('has-moved');
            this.tlCursorIn.play();
        }

        this.mouse.x = e.clientX;
        this.mouse.y = e.clientY;
    }

    hover(e) {
        if (this.delayedCall) this.delayedCall.kill();
        this.el.classList.add('has-hover');
    }

    leave(e) {
        this.el.classList.remove('has-hover');
    }

    destroy() {
        if (isMobile()) return;

        window.removeEventListener('mousemove', this.bindMousemove);
        this.hoverElements.forEach(el => {
            el.removeEventListener('mouseenter', this.bindEnter);
            el.removeEventListener('mouseleave', this.bindLeave);
        });

        cancelAnimationFrame(this.raf);
    }

    animate() {
        this.raf = requestAnimationFrame(() => this.animate());

        this.mouse.lerpedX = lerp(this.mouse.lerpedX, this.mouse.x, 0.1);
        this.mouse.lerpedY = lerp(this.mouse.lerpedY, this.mouse.y, 0.1);

        const rotation = (this.mouse.x - this.mouse.lerpedX) * 0.02;
        transform(this.el, `translate3d(${this.mouse.lerpedX}px,${this.mouse.lerpedY}px,0) rotate(${rotation}deg)`);
    }
}

