import gsap, { reduced, easePrimary, easeGentleIn, easeInstant, easeBlur, easeDirectional, easeMenu, easeQuickSnap, easeText } from '@/gsap'
import { Progress } from './progress'
import { isMobile } from '@/utils/media'
import { Shapes } from './shapes'

export default class Loader {
  /**
   * @param {string} page
   */
  constructor(page) {
    this.loaderWrapper = document.querySelector('.loader-w')
    this.loader = document.querySelector('.loader')
    this.circles = gsap.utils.toArray('.loader__circle')
    this.dots = gsap.utils.toArray('.loader__dot')
    this.tags = document.querySelector('.tagcloud-w')
    this.navigation = document.querySelector('.navigation-w')

    this.scrollDown = document.querySelector('.scroll__down')
    this.indicatorWrapper = document.querySelector('.indicator-w')
    this.indicatorIcon = this.indicatorWrapper?.querySelector('.indicator__icon')
    this.indicatorLabel = this.indicatorWrapper?.querySelector('.indicator__label')

    this.currentPage = page

    // State for rotation control and outro
    this.rotationCount = 0
    this.minRotations = 1
    this.canResolve = false
    this.outroRequested = false
    this.outroExecuted = false

    // Track GSAP timelines to kill on outro
    this.infiniteAnimation = null

    // For resolving outro promise
    this.outroResolve = null

    this.initPageStates(page)
  }

  initShapesOnHome() {
    document.querySelectorAll('[data-shapes]').forEach((el) => {
      const shape = new Shapes(el)
      shape.init()
      // Store if needed
      this.shapesInstances = this.shapesInstances || []
      this.shapesInstances.push(shape)
    })
  }

  initPageStates(page) {
    if (this.indicatorIcon) gsap.set(this.indicatorIcon, { opacity: 0, scale: 0 })
    if (this.tags) gsap.set(this.tags, { scale: 0.8, filter: 'blur(1rem)', opacity: 0 })
    if (this.navigation) gsap.set(this.navigation, { yPercent: -120, opacity: 0 })

    switch (page) {
      case '/':
        this.progressInstance = new Progress()
        this.aiForm = document.querySelector("[data-ai='w']")
        if (this.aiForm) gsap.set(this.aiForm, { opacity: 0 })
        this.initShapesOnHome()
        break
      case '/preorder':
        this.preorderHeroSection = document.querySelector('.s.is--hero')
        this.preorderWrapper = document.querySelector('.preorder-w')
        if (this.preorderWrapper) {
          this.preorderChildren = gsap.utils.toArray(this.preorderWrapper.children)
          gsap.set(this.preorderWrapper, { autoAlpha: 0 })
        }
        break
      case '/specs':
        this.specsHeroSection = document.querySelector('.s.is--hero .section-w')
        this.specsWrapper = document.querySelector('.specs-w')
        this.specsCTA = document.querySelector('.specs__cta')
        if (this.specsWrapper) gsap.set(this.specsWrapper, { autoAlpha: 0 })
        if (this.specsCTA) gsap.set(this.specsCTA, { autoAlpha: 0 })
        break
      case '/fwa':
        this.specsHeroSection = document.querySelector('.s.is--hero .section-w')
        this.specsWrapper = document.querySelector('.specs-w')
        this.specsCTA = document.querySelector('.specs__cta')
        if (this.specsWrapper) gsap.set(this.specsWrapper, { autoAlpha: 0 })
        if (this.specsCTA) gsap.set(this.specsCTA, { autoAlpha: 0 })
        break
    }
  }

  /**
   * Main loader animation sequence.
   * @param {string} page
   * @returns {Promise<void>}
   */
  loaderAnimation(page) {
    return new Promise((resolve, reject) => {
      if (!this.loader || !this.circles.length || !this.dots.length) {
        console.error('Missing loader elements')
        reject('Missing loader elements')
        return
      }

      const mainTl = gsap.timeline({
        onStart: () => {
          document.documentElement.classList.add('is-loading')
        },
        onComplete: () => {
          if (!this.outroExecuted) this.createInfiniteRotation()
          resolve()
        },
      })

      mainTl.add(this.animationIntro())
    })
  }

  /**
   * Loader intro animation (no rotation).
   * @returns {GSAPTimeline}
   */
  animationIntro() {
    const tl = gsap
      .timeline({ defaults: { ease: easeGentleIn, duration: 1 } })
      .from(this.circles, {
        scale: 0,
        stagger: { each: 0.2, from: 'start' },
      })
      .to(this.tags, { scale: 1, filter: 'blur(0rem)', opacity: 1 }, '<')
      .to(this.dots, { opacity: 1, stagger: 0.1, duration: 0.5 }, 0)
    return tl
  }

  /**
   * Creates infinite rotation animation for loader circles.
   * Uses onUpdate to allow immediate outro when ready, not just at repeat boundaries.
   */
  createInfiniteRotation() {
    this.rotationCount = 0
    this.infiniteAnimation = gsap.timeline({
      repeat: -1,
      onRepeat: () => {
        this.rotationCount++
        if (this.rotationCount >= this.minRotations) {
          this.canResolve = true
        }
      },
      onUpdate: () => {
        // console.log("[Loader] onUpdate", this.rotationCount, this.minRotations, this.canResolve, this.outroRequested, this.outroExecuted);

        if (this.canResolve && this.outroRequested && !this.outroExecuted) {
          this.executeOutro()
        }
      },
    })
    this.infiniteAnimation.to(
      this.circles,
      {
        scale: 1,
        rotationY: '+=360',
        rotationZ: '+=360',
        duration: 3,
        stagger: { each: 0.15, from: 'start' },
        ease: easeMenu,
        // ease: easePrimary,
        transformOrigin: 'center center',
      },
      '<'
    )
  }

  /**
   * Triggers the outro animation.
   * @param {string} page
   * @returns {Promise<void>}
   */
  animationOutro(page) {
    this.outroRequested = true
    if (this.canResolve && !this.outroExecuted) {
      this.executeOutro(page)
      return Promise.resolve()
    } else {
      return new Promise((resolve) => {
        this.outroResolve = resolve
      })
    }
  }

  /**
   * Kills all rotation timelines.
   */
  killAllRotations() {
    if (this.infiniteAnimation) {
      this.infiniteAnimation.kill()
      this.infiniteAnimation = null
    }
  }

  /**
   * Executes the outro animation and resolves any pending promises.
   * @param {string} [page]
   * @returns {GSAPTimeline}
   */
  executeOutro(page) {
    this.outroExecuted = true

    const tl = gsap.timeline({
      defaults: { ease: 'expo.out', duration: 0.8 },
      onStart: () => {
        gsap.to(this.tags, { scale: 1.1, filter: 'blur(1rem)', opacity: 0 })
        if (this.outroResolve) {
          this.outroResolve()
          this.outroResolve = null
        }
      },
      onComplete: () => {
        document.documentElement.classList.remove('is-loading')
      },
    })

    tl.to(this.circles, {
      opacity: 0,
      filter: 'blur(1rem)',
      stagger: {
        amount: 0.8,
        each: 0.15,
        from: 'start',
      },
      overwrite: 'auto',
      onStart: () => {
        this.killAllRotations()
      },
    })

    const currentPage = page || this.currentPage
    this.animatePageOutro(tl, currentPage)

    return tl
  }

  /**
   * Handles page-specific outro animations.
   * @param {GSAPTimeline} tl
   * @param {string} currentPage
   */
  animatePageOutro(tl, currentPage) {
    switch (currentPage) {
      case '/':
        if (this.aiForm) tl.to(this.aiForm, { opacity: 1 }, '<')
        this.animateNavigationIn(tl)
        this.animateIndicatorIn(tl)
        if (this.progressInstance)
          tl.call(
            () => {
              this.progressInstance.init()
            },
            null,
            '<'
          )
        break
      case '/preorder':
        this.animateNavigationIn(tl)
        if (this.preorderHeroSection) tl.to(this.preorderHeroSection, { '--progress': 1, ease: easePrimary, duration: 2 }, '<')
        if (this.preorderWrapper) tl.to(this.preorderWrapper, { autoAlpha: 1, ease: easePrimary, duration: 0.4 }, '<')
        if (this.indicatorLabel) tl.to(this.indicatorLabel, { yPercent: 100, autoAlpha: 0, filter: 'blur(1rem)' }, '<')
        break
      case '/specs':
        this.animateNavigationIn(tl)
        if (this.specsWrapper) tl.to(this.specsWrapper, { autoAlpha: 1, ease: easePrimary, duration: 1 }, '<')
        if (this.specsHeroSection) tl.to(this.specsHeroSection, { '--progress': 1, ease: easePrimary, duration: 2 }, '<')
        if (this.specsCTA) tl.to(this.specsCTA, { autoAlpha: 1, ease: easePrimary, duration: 0.8 }, '<')
        if (this.indicatorLabel) tl.to(this.indicatorLabel, { yPercent: 100, autoAlpha: 0 }, '<')
        break
      case '/fwa':
        this.animateNavigationIn(tl)
        if (this.specsWrapper) tl.to(this.specsWrapper, { autoAlpha: 1, ease: easePrimary, duration: 1 }, '<')
        if (this.specsHeroSection) tl.to(this.specsHeroSection, { '--progress': 1, ease: easePrimary, duration: 2 }, '<')
        if (this.specsCTA) tl.to(this.specsCTA, { autoAlpha: 1, ease: easePrimary, duration: 0.8 }, '<')
        if (this.indicatorLabel) tl.to(this.indicatorLabel, { yPercent: 100, autoAlpha: 0 }, '<')
        break
      default:
        console.warn('Unknown page:', currentPage)
        this.animateNavigationIn(tl)
    }
  }

  /**
   * Animates navigation in.
   * @param {GSAPTimeline} tl
   */
  animateNavigationIn(tl) {
    if (this.navigation) tl.to(this.navigation, { yPercent: 0, opacity: 1, duration: 1, ease: easeGentleIn }, '<')
  }

  /**
   * Animates indicator in for the home page.
   * @param {GSAPTimeline} tl
   */
  animateIndicatorIn(tl) {
    if (this.indicatorLabel)
      if (!isMobile()) tl.to(this.indicatorLabel, { text: '[ discover specs ]' }, '<.4')
      else tl.to(this.indicatorLabel, { text: '[ specs ]' }, '<.4')

    if (this.indicatorIcon) tl.to(this.indicatorIcon, { opacity: 1, scale: 1 }, '<.4')
  }
}

import { Observe } from "./_/observe";
import { Scroll } from '@/scroll'
import gsap, { easeBlur, easeMenu } from "@/gsap";
import { html } from '@/utils/environment';
import Gl from "@/gl/Gl";
import ScrollController from "./ScrollController";
import Hey from '../utils/hey'

const CLASS = {
  OPEN: `has-menu-open`,
  MODAL_OPEN: `has-modal-open`,
}

export class Menu extends Observe {
  static instance = null;

  constructor(element) {
    super(element);

    if (Menu.instance) return Menu.instance;
    Menu.instance = this;

    this.gl = new Gl();
    this.stops = [0, 0.125, 0.25, 0.375, 0.375, 0.5, 0.625, 0.742, 0.81, 1];

    // Core nodes
    this.$menu = element; // <nav id="main-nav">, the menu container
    this.$menuToggle = document.getElementById('menu-toggle'); // burger button
    this.$navLine = this.$menu.querySelector('.nav__line');
    this.$navItems = this.$menu.querySelectorAll('.nav__item');
    this.$navLinks = this.$menu.querySelectorAll('.nav__link');
    this.$navCTA = this.$menu.querySelector('.nav__cta');
    this.$navBurger = this.$menu.querySelector('.nav__burger');
    this.$navBurgerCircles = this.$menu.querySelectorAll('.nav__burger circle');
    this.$navLogo = document.querySelector('.nav__logo');
    this.$navLogoCircles = document.querySelectorAll('.nav__logo circle:not(:nth-child(5))');

    gsap.set(this.$menu, { height: "4.6rem" });

    // Event handlers
    this.handleMenuClick = this.handleMenuClick.bind(this);
    this.handleFocusTrap = this.handleFocusTrap.bind(this);
    this.closeBind = (e) => { if (e.key === "Escape") this.close(); };
    this.outsideClickBind = (e) => {
      if (!this.$menu.contains(e.target) && e.target !== this.$menuToggle) {
        this.close();
      }
    };

    // --- Event listeners ---
    // Only the menu toggle opens/closes menu
    this.$menuToggle.addEventListener('click', this.toggle.bind(this));
    this.$menuToggle.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        this.toggle();
      }
    });

    // Keyboard ESC to close
    document.addEventListener('keyup', this.closeBind);

    // Menu: click on link/call-to-action (not the burger)
    this.$menu.addEventListener('click', this.handleMenuClick);

    // Burger hover
    this.$menuToggle.addEventListener('mouseenter', () => this.tlBurger?.play());
    this.$menuToggle.addEventListener('mouseleave', () => this.tlBurger?.pause().progress(0));

    // Accessibility attributes
    this.$menu.setAttribute('role', 'navigation');
    this.$menu.setAttribute('aria-label', 'Main navigation');
    this.$menu.setAttribute('hidden', '');
    this.$menuToggle.setAttribute('aria-expanded', 'false');

    this.init();
  }

  init() {
    this.tlMenu = gsap.timeline({
      paused: true,
      defaults: { ease: easeBlur, duration: 0.6 },
    })
    this.tlMenu
      .to(this.$menu, { height: "auto", backgroundColor: "rgba(5, 13, 21, 0.8)" })
      // .fromTo(this.$menu, { height: "4.6rem", backgroundColor: "rgba(5, 13, 21, 0.08)" }
      //   , { height: "auto", backgroundColor: "rgba(5, 13, 21, 0.8)" })
      // this.tlMenu
      //   .fromTo(this.$menu, { height: "4.6rem", backgroundColor: "rgba(255, 255, 255, 0.08)" }
      //     , { height: "auto", backgroundColor: "rgba(255, 255, 255, 0.08)" })

      .fromTo(this.$navLine, { scale: 0, transformOrigin: "center center" }, { scale: 1, ease: "expo.out" }, '<.2')
      .fromTo(this.$navLinks, { yPercent: -100 }, { yPercent: 0, stagger: 0.05, clearProps: true }, "<")
      .fromTo(this.$navCTA, {
        opacity: 0,
        filter: "blur(.5rem)",
        scale: 1.05
      }, {
        opacity: 1,
        filter: "blur(0rem)",
        scale: 1
      }, ">-.6")
    // .to(this.$menu, { backgroundColor: "rgba(5, 13, 21, 0.8)" })


    this.tlBurger = gsap.timeline({ paused: true })
      .to(this.$navLogo, { rotate: 180, ease: easeMenu })
      .to(this.$navBurgerCircles, {
        scale: 0,
        transformOrigin: "center center",
        stagger: { each: 0.1, from: "random", repeat: -1, yoyo: true },
        ease: easeMenu,
        duration: 0.3
      }, "<")
      .to(this.$navLogoCircles, {
        scale: 0,
        transformOrigin: "center center",
        stagger: { each: 0.1, from: "random" },
        ease: easeMenu,
        duration: 0.3
      }, ">-.2");
  }

  handleMenuClick(e) {
    // Ignore clicks from menu toggle (burger), only handle menu content ONLY HOMEPAGE!!
    if (Hey.PAGE_SLUG === '/') {
      const navLink = e.target.closest('.nav__link');
      if (navLink && navLink.hasAttribute('data-anchor')) {
        const anchorIdx = Number(navLink.dataset.anchor);
        const anchor = ScrollController.getSectionAnchor(anchorIdx);
        console.log(anchor);

        Scroll.scrollTo(anchor, {
          easing: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
        });
        this.close();
        return;
      }
    }

    if (e.target.closest('.nav__cta')) {
      this.close();
      return;
    }
  }

  open() {
    html.classList.add(CLASS.OPEN);
    this.$menuToggle.setAttribute('aria-expanded', 'true');
    this.$menu.removeAttribute('hidden');
    this.$menu.querySelector('.nav__list')?.removeAttribute('inert');
    this.$menu.querySelector('.nav__cta')?.removeAttribute('inert');
    // this.$navLinks[0]?.focus();
    this.tlMenu.timeScale(1).play();

    document.addEventListener('click', this.outsideClickBind);
    document.addEventListener('keydown', this.handleFocusTrap);
  }

  close() {
    html.classList.remove(CLASS.OPEN);
    this.$menuToggle.setAttribute('aria-expanded', 'false');
    this.$menu.setAttribute('hidden', '');
    this.$menu.querySelector('.nav__list')?.setAttribute('inert', '');
    this.$menu.querySelector('.nav__cta')?.setAttribute('inert', '');
    this.tlMenu.timeScale(1.75).reverse();

    document.removeEventListener('click', this.outsideClickBind);
    document.removeEventListener('keydown', this.handleFocusTrap);
    this.$menuToggle.focus();
  }


  handleFocusTrap(e) {
    if (!html.classList.contains(CLASS.OPEN)) return;
    if (e.key !== 'Tab') return;

    const focusable = Array.from(this.$menu.querySelectorAll('a, button, [tabindex]:not([tabindex="-1"])'))
      .filter(el => !el.hasAttribute('disabled') && el.offsetParent !== null);
    if (focusable.length === 0) return;

    const first = focusable[0];
    const last = focusable[focusable.length - 1];

    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  toggle() {
    if (html.classList.contains(CLASS.OPEN)) {
      this.close();
      this.gl.audio.playUI('uiMenuClose');
    } else {
      this.open();
      this.gl.audio.playUI('uiMenuOpen');
    }
  }

  destroy() {
    document.removeEventListener('keyup', this.closeBind);
    document.removeEventListener('click', this.outsideClickBind);
    document.removeEventListener('keydown', this.handleFocusTrap);
    this.$menu?.removeEventListener('click', this.handleMenuClick);

    this.tlMenu?.kill();
    this.tlBurger?.kill();

    this.$menuToggle?.setAttribute('aria-expanded', 'false');
    html.classList.remove(CLASS.OPEN);

    this.tlMenu = null;
    this.tlBurger = null;
    this.$menu = null;
    Menu.instance = null;
  }
}

import { Observe } from "./_/observe";
