export class Scramble extends Observe {
    constructor(element) {
        super(element);

        this.el = element;

        this.events = {
            mouseenter: {
                wrap: 'hover'
            }
        }


        this.needOnMobile = true;

        if (typeof this.el.dataset.desktop == 'string') {
            this.needOnMobile = false;
        }

        // Options
        this.auto = typeof this.el.dataset.auto == 'string';
        this.delay = typeof this.el.dataset.delay == 'string' ? parseFloat(this.el.dataset.delay) : 0;
        this.stagger = typeof this.el.dataset.stagger == 'string' ? parseFloat(this.el.dataset.stagger) : 0.2;
        this.duration = typeof this.el.dataset.duration == 'string' ? parseFloat(this.el.dataset.duration) : 1;
        this.iteration = typeof this.el.dataset.iteration == 'string' ? parseFloat(this.el.dataset.iteration) : 1;

        this.init();
        // this.isScrolling()
    }

    init() {

        if (isMobile && !this.needOnMobile) {
            return;
        }

        this.split = new SplitText(this.el, {
            type: 'chars, words'
        });
        // this.hide(0, 0);

    }

    ready() {
        if (isMobile && !this.needOnMobile) {
            return;
        }

        if (this.auto) {
            this.display(this.delay, this.duration, this.stagger, this.iteration);
            gsap.delayedCall(this.delay, () => {
                this.el.classList.add('is-inview');
            });
        }
    }

    isIn = () => {
        if (gsap.reduced) return;
        this.display(.2, this.duration, this.stagger, this.iteration);
    };

    isOut = () => {
        if (gsap.reduced) return;
        this.hide();
    };

    toggle(e) {

        if (isMobile && !this.needOnMobile) {
            return;
        }

        if (e.mode == 'enter') {
            this.display(this.delay, this.duration, this.stagger, this.iteration);

        } else {
            this.hide();
        }
    }

    display(delay = 0, duration = 0.1, stagger = 0.2, iteration = 1) {

        if (isMobile && !this.needOnMobile) {
            return;
        }

        if (this.split == undefined) {
            return;
        }

        if (this.tl != undefined) {
            this.tl.kill();
        }
        this.tl = gsap.timeline();

        for (let index = 0; index < iteration; index++) {
            this.tl.to(this.split.chars, {
                alpha: index % 2 == 0 ? 1 : 0,
                duration: duration / iteration,
                delay: index == 0 ? delay : 0,
                ease: "power2.out",
                stagger: {
                    amount: stagger,
                    from: "random"
                }
            });
        }
    }

    hide(delay = 0, duration = 0.1) {
        if (isMobile && !this.needOnMobile) {
            return;
        }

        if (this.split == undefined) {
            return;
        }

        if (this.tl != undefined) {
            this.tl.kill();
        }
        this.tl = gsap.timeline();

        this.tl.to(this.split.chars, {
            alpha: 0.001,
            duration,
            delay,
            ease: "power2.in",
            stagger: {
                amount: 0.05,
                from: "random"
            }
        });
    }

    isScrolling() {
        // Create timeline for hero section animation with film roll effect
        const heroTl = gsap.timeline({
            scrollTrigger: {
                trigger: ".s",
                start: "top top", // Start at the very beginning
                end: "+=50% top", // End after 400px of scrolling - longer duration
                scrub: 1, // Slower scrub for smoother animation
                // markers: true
            }
        });

        // Animate each element in the header content with a film roll effect
        gsap.utils.toArray(".s.is--hero .section-w > *").forEach((element, index) => {
            // gsap.utils.toArray(".header-content > *").forEach((element, index) => {
            heroTl.to(
                element,
                {
                    rotationX: 90,
                    y: -30,
                    scale: 0.8, // Scale down as it rotates away
                    opacity: 0,
                    filter: "blur(1rem)", // Add blur effect
                    ease: "power3.inOut", // Better easing
                    transformOrigin: "center top"
                },
                index * 0.08
            ); // More spacing between elements
        });
    }

    destroy() {
        if (isMobile && !this.needOnMobile) {
            return;
        }

        if (this.tl != undefined) {
            this.tl.kill();
        }
    }

}

import { Observe } from "./_/observe";
import gsap from "@/gsap";
import SplitText from "gsap/SplitText";
gsap.registerPlugin(SplitText);

export class SplitLines extends Observe {
    constructor(element) {
        super(element);

        this.el = element;
        // Options
        this.revealLines = this.el.dataset.releaveLines === 'true';
        this.delay = parseFloat(this.el.dataset.delay) || 0.0;
        this.stagger = parseFloat(this.el.dataset.stagger) || 0.02;
        this.hide = this.el.dataset.hide || false;

        // console.log(this.revealLines, this.delay, this.stagger);

        this.init();
        this.create();
        // this.isOut();

    }

    init() {
        this.el.setAttribute('aria-label', this.element.textContent);
    }

    destroy() {
        this.clear()
    }

    ///////////////
    // Callbacks
    ///////////////
    onResize = () => {
        this.reSplit()
    }

    ///////////////
    // Methods
    ///////////////
    split() {
        this.splitObject = new SplitText(this.el, {
            type: "lines",
            linesClass: "u-lines-split"
        });
        this.splitObject.lines.forEach((line, i) => {
            line.style.setProperty('--line-index', i)
            line.setAttribute('aria-hidden', 'true')
        });

        // if (this.revealLines) {
        //     // Maybe a better way to do this with CSS progress
        //     this.tlScroll = gsap.timeline({
        //         scrollTrigger: {
        //             trigger: this.el,
        //             start: "top bottom-=25%",
        //             end: "bottom center",
        //             scrub: 1
        //         }
        //     })

        //     for (let i = 0; i < this.splitObject.lines.length; i++) {
        //         this.tlScroll.fromTo(this.splitObject.lines[i], {
        //             opacity: 0.25
        //         }, {
        //             opacity: 1
        //         })
        //     }
        // }
    }

    reSplit() {
        this.splitObject?.revert?.();

        requestAnimationFrame(() => {
            this.split();
        })
    }

    create() {
        if (gsap.reduced) return;

        this.split();
    }

    isIn = () => {
        if (gsap.reduced) return;

        if (!this.hide)
            this.element.classList.add("is-inview");


    };

    isOut = () => {
        if (gsap.reduced) return;

        if (this.element.classList.contains("is-inview")) {
            // this.element.classList.remove("is-inview");
            this.hide = false
        }
    };

    clear() {
        this.splitObject?.lines?.forEach((line) => line.style.removeProperty('--line-index'));
        this.splitObject?.revert?.();
        this.splitObject = null;

        this.tlScroll?.kill?.();
        this.tlScroll = null;
    }


}

import TagCloud from "TagCloud";

export class Tags {
  constructor(selector, tags, options = {}) {
    this.selector = selector;
    this.tags = tags;
    this.baseOptions = options;
    this.instance = null;

    this.selector = '.tagcloud-w';

    this.baseOptions = {
      radius: 336,
      maxSpeed: "normal",
      initSpeed: "fast",
      direction: 135,
      keep: false
      //  useItemInlineStyles: true // Make sure this is true
    };

    this.tags = [
      // "[      USB-C universal charging      ]",
      "[      EQualizer      ]",
      "[      noise control      ]",
      "[      AI assistant      ]"
    ];


    this.init();
    this.addListeners();
  }
  getResponsiveRadius() {
    const { baseViewport = 1440, baseRadius = 400, minRadius = 150 } = this.baseOptions;
    const currentViewport = window.innerWidth;

    return Math.max(minRadius, (currentViewport / baseViewport) * baseRadius);
  }

  init() {
    const radius = this.getResponsiveRadius();
    this.instance = new TagCloud(this.selector, this.tags, {
      ...this.baseOptions,
      radius: radius
    });

  }

  update() {
    if (this.instance) {
      if (Array.isArray(this.instance)) {
        this.instance.forEach(cloud => cloud.destroy());
      } else {
        // NEED TO FIX THTA
        // this.instance.destroy();
      }
    }
    this.init();
  }

  addListeners() {
    let resizeTimer;
    window.addEventListener('resize', () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => this.update(), 200);
    });
  }

}

import { Observe } from "./_/observe";
import gsap from "@/gsap";
import SplitText from "gsap/SplitText";
gsap.registerPlugin(SplitText);

import { computeParams } from "./_/index";

const split = (element) => {
  const unsplit = element.innerHTML;
  const type = element.dataset.type || "words";
  const split = new SplitText(element, { type });

  element.setAttribute("aria-label", unsplit);
  split.result = split[type];
  return split;
};

